// lab/s7/d04 —— repo 层：用内存 slice 模拟表，把查询与写入真的跑出来
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d04
//
// 本机没有 PostgreSQL，所以 repo 层用 []Category 模拟一张表。
// **这是逻辑模拟**：S7 d11 联调时要把同样的逻辑跑在真 SQL 上。
// 但模拟的价值在于：今天能把查询条件、越权判断、乐观锁这三件事的逻辑先捋清楚。

package main

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

func pad(s string, n int) string {
	w := utf8.RuneCountInString(s)
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

// ============ model：与 d03 的 DDL 一一对应 ============
type Category struct {
	ID        string  // UUID
	FamilyID  *string // ★ nil = 预置字典项
	ParentID  *string // ★ nil = 一级分类
	Name      string
	Icon      string
	Color     *string
	Type      string // expense | income
	IsActive  bool
	SortOrder int
	Version   int64
	DeletedAt *string // 软删
}

// ============ repo 层：只碰表，不管业务 ============

// 三种「找不到」，必须区分清楚 —— 这是 repo 唯一该做的事
var (
	ErrNotFound   = errors.New("category not found")            // 行不存在
	ErrVersionCon = errors.New("version conflict")              // 乐观锁冲突
	ErrDuplicate  = errors.New("duplicate name in same family") // 唯一索引冲突
)

type CategoryRepo struct {
	rows []Category // 模拟 finance.finance_category 这张表
	log  []string   // 记录实际发出的查询条件，方便对照真 SQL
}

func newRepo(seed []Category) *CategoryRepo {
	return &CategoryRepo{rows: append([]Category(nil), seed...)}
}

func (r *CategoryRepo) record(format string, a ...any) {
	r.log = append(r.log, fmt.Sprintf(format, a...))
}

// List 对应 GET /api/finance/categories
// 注意它的查询条件与 d03 生成的 SQL 一一对应。
func (r *CategoryRepo) List(familyID string, onlyActive bool) []Category {
	r.record("WHERE (family_id = %q OR family_id IS NULL) AND deleted_at IS NULL%s ORDER BY sort_order ASC",
		familyID, map[bool]string{true: " AND is_active = true", false: ""}[onlyActive])

	out := make([]Category, 0, 8) // ★ make 出来的空 slice 不是 nil —— 序列化成 [] 而不是 null
	for _, c := range r.rows {
		if c.DeletedAt != nil {
			continue // 软删的行永远不返回
		}
		// 预置项（family_id == nil）对所有家庭可见
		if c.FamilyID != nil && *c.FamilyID != familyID {
			continue // ← ★ 这是多租户隔离的全部秘密
		}
		if onlyActive && !c.IsActive {
			continue
		}
		out = append(out, c)
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].SortOrder < out[j].SortOrder })
	return out
}

// GetByID 对应按 id 查单条。★ 注意 family_id 也在条件里 —— 越权自然就 404 了。
func (r *CategoryRepo) GetByID(familyID, id string) (*Category, error) {
	r.record("WHERE id = %q AND (family_id = %q OR family_id IS NULL) AND deleted_at IS NULL", id, familyID)
	for i := range r.rows {
		c := &r.rows[i]
		if c.ID != id || c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			return nil, ErrNotFound // ★ 越权 = 不存在，不是「无权限」
		}
		return c, nil
	}
	return nil, ErrNotFound
}

// Create 对应 POST /api/finance/categories
func (r *CategoryRepo) Create(c Category) (*Category, error) {
	r.record("INSERT INTO finance_category (family_id, parent_id, name, icon, color, type, is_active, sort_order, version) VALUES (...)")
	for _, e := range r.rows {
		if e.DeletedAt != nil || e.Type != c.Type || e.Name != c.Name {
			continue
		}
		// 预置项之间也要查重：两个 family_id 都为 nil 时应视为同一域
		sameScope := (e.FamilyID == nil && c.FamilyID == nil) ||
			(e.FamilyID != nil && c.FamilyID != nil && *e.FamilyID == *c.FamilyID)
		if sameScope {
			return nil, ErrDuplicate
		}
	}
	c.Version = 1
	c.IsActive = true
	r.rows = append(r.rows, c)
	return &c, nil
}

// Archive 对应 PUT /categories/{id}/archive。★ 乐观锁在这里生效。
func (r *CategoryRepo) Archive(familyID, id string, version int64) error {
	r.record("UPDATE finance_category SET is_active=false, version=version+1 WHERE id=%q AND family_id=%q AND version=%d",
		id, familyID, version)
	for i := range r.rows {
		c := &r.rows[i]
		if c.ID != id || c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			return ErrNotFound // 预置项（nil）在这里被放行 —— ★ 所以预置项可以停用
		}
		if c.Version != version {
			return ErrVersionCon
		}
		c.IsActive = false
		c.Version++
		return nil
	}
	return ErrNotFound
}

// Restore 对应 POST /categories/{id}/restore
func (r *CategoryRepo) Restore(familyID, id string, version int64) error {
	r.record("UPDATE finance_category SET is_active=true, version=version+1 WHERE id=%q AND family_id=%q AND version=%d",
		id, familyID, version)
	for i := range r.rows {
		c := &r.rows[i]
		if c.ID != id || c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			return ErrNotFound
		}
		if c.Version != version {
			return ErrVersionCon
		}
		c.IsActive = true
		c.Version++
		return nil
	}
	return ErrNotFound
}

func main() {
	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }
	ptr := func(s string) *string { return &s }
	yes := "2026-10-15T10:00:00Z"

	seed := []Category{
		{ID: "p-01", FamilyID: nil, ParentID: nil, Name: "餐饮", Icon: "food", Color: ptr("#FF6B35"), Type: "expense", IsActive: true, SortOrder: 10, Version: 1},
		{ID: "p-02", FamilyID: nil, ParentID: nil, Name: "交通", Icon: "bus", Color: ptr("#2F6FED"), Type: "expense", IsActive: true, SortOrder: 20, Version: 1},
		{ID: "p-03", FamilyID: nil, ParentID: nil, Name: "工资", Icon: "wallet", Color: ptr("#52C41A"), Type: "income", IsActive: true, SortOrder: 30, Version: 1},
		{ID: "c-01", FamilyID: ptr("fam-A"), ParentID: ptr("p-01"), Name: "买菜", Icon: "cart", Color: nil, Type: "expense", IsActive: true, SortOrder: 11, Version: 1},
		{ID: "c-02", FamilyID: ptr("fam-A"), ParentID: nil, Name: "房贷", Icon: "home", Color: nil, Type: "expense", IsActive: false, SortOrder: 40, Version: 3},
		{ID: "c-03", FamilyID: ptr("fam-B"), ParentID: nil, Name: "宠物", Icon: "paw", Color: nil, Type: "expense", IsActive: true, SortOrder: 15, Version: 1},
		{ID: "c-04", FamilyID: ptr("fam-A"), ParentID: nil, Name: "已删的分类", Icon: "box", Color: nil, Type: "expense", IsActive: true, SortOrder: 50, Version: 1, DeletedAt: &yes},
	}

	repo := newRepo(seed)
	const famA = "fam-A"

	H("1. List：★ 预置项 + 本家庭项，别的家庭的一项都看不到")
	all := repo.List(famA, false)
	L(pad("ID", 8) + pad("名称", 12) + pad("归属", 10) + pad("父级", 8) + pad("类型", 9) + pad("启用", 6) + pad("sort", 6) + "version")
	for _, c := range all {
		owner := "预置"
		if c.FamilyID != nil {
			owner = *c.FamilyID
		}
		parent := "—"
		if c.ParentID != nil {
			parent = *c.ParentID
		}
		mark := "true"
		if !c.IsActive {
			mark = "false"
		}
		L(pad(c.ID, 6) + pad(c.Name, 10) + pad(owner, 8) + pad(parent, 6) +
			pad(c.Type, 7) + pad(mark, 4) + pad(fmt.Sprint(c.SortOrder), 4) + fmt.Sprint(c.Version))
	}
	L("")
	L("关键验证：")
	L("  · fam-B 的「宠物」在列表里吗？      → " + contains(all, "c-03") + "（不该在）")
	L("  · 软删的「已删的分类」在列表里吗？  → " + contains(all, "c-04") + "（不该在）")
	L("  · 已停用的「房贷」在列表里吗？      → " + contains(all, "c-02") + "（应该在，列表页要显示）")
	L("  · 预置项「餐饮」在列表里吗？        → " + contains(all, "p-01") + "（应该在）")

	H("2. List(familyID, onlyActive=true)：★ 记账选择器用的过滤")
	picker := repo.List(famA, true)
	names := make([]string, 0, len(picker))
	for _, c := range picker {
		names = append(names, c.Name)
	}
	L("items = " + strings.Join(names, ", "))
	L("★ 「房贷」没了 —— 它 is_active=false。选择器不能出现停用项（PRD 4.5.9）。")
	L("★ 但 List(familyID, false) 里它还在 —— 列表页要能看见并恢复它。")
	L("★ 两个接口/两种过滤，不是两个接口：同一个 GET 加一个 query 即可。")
	L("  契约里标注：「记账与编辑的选择器只返回未停用项」（PRD 4.8 L705）。")

	H("3. GetByID：★ 越权返回什么")
	cases := []struct{ desc, id string }{
		{"本家庭的分类", "c-01"},
		{"预置项（family_id 为 nil）", "p-01"},
		{"别家的分类", "c-03"},
		{"软删的分类", "c-04"},
		{"根本不存在的 id", "cat-9999"},
	}
	L(pad("场景", 30) + pad("结果", 14) + "说明")
	for _, c := range cases {
		got, err := repo.GetByID(famA, c.id)
		switch {
		case err != nil:
			note := ""
			if errors.Is(err, ErrNotFound) {
				note = "→ HTTP 404（不是 403）"
			}
			L(pad(c.desc, 28) + pad("ErrNotFound", 12) + note)
		default:
			L(pad(c.desc, 28) + pad("OK", 12) + got.Name)
		}
	}
	L("")
	L("★ 「别家的分类」和「不存在的 id」返回完全一样 —— 这就是防枚举。")
	L("  如果这里返 403，攻击者就能区分「这个 id 存在但不是我的」，")
	L("  拿到一份「哪些 id 真实存在」的清单，为撞库提供素材。")

	H("4. Create：★ 同域查重（含预置项之间）")
	newOnes := []struct {
		desc string
		c    Category
	}{
		{"A 家新建「宠物」", Category{ID: "x-01", FamilyID: ptr(famA), Name: "宠物", Type: "expense", Icon: "paw"}},
		{"A 家再建「宠物」", Category{ID: "x-02", FamilyID: ptr(famA), Name: "宠物", Type: "expense", Icon: "paw"}},
		{"B 家建「宠物」（B 家已有）", Category{ID: "x-03", FamilyID: ptr("fam-B"), Name: "宠物", Type: "expense", Icon: "paw"}},
		{"预置「餐饮」再来一个", Category{ID: "x-04", FamilyID: nil, Name: "餐饮", Type: "expense", Icon: "food"}},
		{"预置「餐饮」但 type=income", Category{ID: "x-05", FamilyID: nil, Name: "餐饮", Type: "income", Icon: "food"}},
		{"A 家建「教育」", Category{ID: "x-06", FamilyID: ptr(famA), Name: "教育", Type: "expense", Icon: "book"}},
	}
	L(pad("操作", 30) + pad("结果", 16) + "说明")
	for _, n := range newOnes {
		got, err := repo.Create(n.c)
		switch {
		case errors.Is(err, ErrDuplicate):
			L(pad(n.desc, 28) + pad("ErrDuplicate", 14) + "→ HTTP 422")
		case err != nil:
			L(pad(n.desc, 28) + pad("err", 14) + err.Error())
		default:
			L(pad(n.desc, 28) + pad("OK", 14) + "id=" + got.ID + " version=" + fmt.Sprint(got.Version) + " is_active=" + fmt.Sprint(got.IsActive))
		}
	}
	L("")
	L("★ 三条结论：")
	L("  1. 同域同名同类被拒（B 家建「宠物」失败）→ 422")
	L("  2. ★ 预置项之间也要查重：family_id 都是 nil 时视为同一域")
	L("     这靠 d03 里那个 COALESCE(family_id, 零值) 的唯一索引保证。")
	L("     如果索引写成 (family_id, type, name)，NULL 不参与唯一判断，")
	L("     就会出现一百个叫「餐饮」的预置项。")
	L("  3. 同名但 type 不同是允许的（「餐饮」expense 与 income 各一个）")

	H("5. Archive / Restore：★ 乐观锁与预置项可停用")
	L("① 用正确的 version 停用本家庭分类 c-02（当前 version=3）")
	err := repo.Archive(famA, "c-02", 3)
	L("   结果 = " + errText(err) + " ← version 现在是 4")
	got, _ := repo.GetByID(famA, "c-02")
	L("   c-02 现在 is_active=" + fmt.Sprint(got.IsActive) + " version=" + fmt.Sprint(got.Version))

	L("")
	L("② 用过期的 version 再停一次（模拟两个设备同时操作）")
	err = repo.Archive(famA, "c-02", 3)
	L("   结果 = " + errText(err) + " ← RowsAffected=0 → HTTP 409")

	L("")
	L("③ 停用预置项 p-01（family_id 为 nil）")
	err = repo.Archive(famA, "p-01", 1)
	L("   结果 = " + errText(err) + " ← ★ 允许！PRD 4.5.9：预置项可停用不可删")
	got, _ = repo.GetByID(famA, "p-01")
	L("   p-01 现在 is_active=" + fmt.Sprint(got.IsActive))
	L("")
	L("   这意味着「停用」只对**本家庭**生效 —— 但 p-01 是所有家庭共享的一行！")
	L("   ★★ 这是本设计里最需要想清楚的一点，d10 专门讲。")

	L("")
	L("④ 恢复")
	err = repo.Restore(famA, "p-01", got.Version)
	L("   结果 = " + errText(err))
	got, _ = repo.GetByID(famA, "p-01")
	L("   p-01 恢复后 is_active=" + fmt.Sprint(got.IsActive) + " version=" + fmt.Sprint(got.Version))

	L("")
	L("⑤ 越权停用别家的 c-03")
	err = repo.Archive(famA, "c-03", 1)
	L("   结果 = " + errText(err) + " ← 又是 404，不是 403")

	H("6. repo 层实际发出了哪些查询（对照 d03 的 DryRun SQL）")
	for i, q := range repo.log {
		L(fmt.Sprintf("  %2d. %s", i+1, q))
	}
	L("")
	L("★ 对照 d03 生成的 SQL：条件一一相同，差别只在模拟器把 SQL 换成了 for 循环。")
	L("  真库上同一条条件会编译成 WHERE (family_id = $1 OR family_id IS NULL)")
	L("  AND deleted_at IS NULL ORDER BY sort_order ASC。")

	H("6.5 ★★今天发现的一个真问题：d03 的 archive SQL 和 d04 的逻辑对不上")
	L("第 5 节第③ 小步，「停用预置项 p-01」在内存模拟里成功了（nil）。")
	L("但看第 6 节第 17 条发出的条件：")
	L("    UPDATE ... WHERE id=\"p-01\" AND family_id=\"fam-A\" AND version=1")
	L("")
	L("★ 问题：p-01 的 family_id 是 **NULL**（预置项）。")
	L("  SQL 语义是 `family_id = 'fam-A'`，NULL = 'fam-A' 的结果是 NULL（不是 true），")
	L("  所以这条 UPDATE 在真库上**一行都匹配不到**，RowsAffected=0。")
	L("  → 真库上「停用预置项」会返回 404，而内存模拟返回成功。")
	L("  → 这是模拟器与真 SQL 的行为差异：模拟器的 for 循环用 Go 的 != 判断，")
	L("    而 SQL 的 NULL 比较有三值逻辑。")
	L("")
	L("两条修法，各有代价：")
	L("")
	L("  修法 A：把 archive 的条件改成 `family_id = ? OR family_id IS NULL`")
	L("    → 预置项能停用了，但 p-01 是**所有家庭共享的一行**。")
	L("      A 家停了它，B 家也看不到了。这是「一家的操作影响别人」。")
	L("")
	L("  修法 B：新增一张 finance_category_preference 表，记 (family_id, category_id, is_active)")
	L("    → 预置项的停用状态按家庭各存一份，互不影响。")
	L("    → 代价是查询要多 join 一张表，列表返回的 is_active 要按 preference 覆盖。")
	L("")
	L("★ 这个矛盾不是今天能拍板的，它正是 PRD 4.7「family_id 可空 = 预置字典 +")
	L("  家庭自定义」这句话没有讲透的地方。S7 d10 专门讲这一条。")
	L("★ 今天要记住的教训是：**模拟器不等于真库**。")
	L("  d11 联调时如果你没把这段跑在真 SQL 上，这个 bug 会活到上线。")
	L("")
	H("7. ★repo 层「不许做」的三件事")
	L("① 不许写业务流程。Archive 里出现「预置项不能停用」这种判断就是越界 ——")
	L("   它应该由 service 层判断，repo 只管把 SQL 发出去。")
	L("   （上面 Archive 允许预置项通过，恰恰是因为 repo 不做业务判断。）")
	L("")
	L("② 不许跨 schema 查询。tech-plan §3.2 第 2 条：repo 不得 select 别的 schema 的表。")
	L("   所以「这个分类有没有被流水引用」不能靠 join finance_transaction ——")
	L("   那是 service 层通过 platform 接口去问 finance_transaction 所属的另一个 repo。")
	L("")
	L("③ 不许把「找不到」和「无权限」分成两个错误返回。")
	L("   repo 只有 ErrNotFound 一个 not-found 错误，越权也走它。")
	L("   理由就是第3 节：区分开等于给攻击者发 id 存在性的清单。")

	H("8. 自查")
	checks := []struct {
		name string
		ok   bool
	}{
		{"预置项对所有家庭可见", contains2(repo.List("fam-Z", false), "p-01")},
		{"别家庭的项不可见", !contains2(repo.List(famA, false), "c-03")},
		{"软删的项不可见", !contains2(repo.List(famA, false), "c-04")},
		{"停用的项在列表可见、选择器不可见", contains2(repo.List(famA, false), "c-02") && !contains2(repo.List(famA, true), "c-02")},
		{"越权与不存在返回同一个错误", errors.Is(mustErr(repo.GetByID(famA, "c-03")), ErrNotFound) && errors.Is(mustErr(repo.GetByID(famA, "cat-9999")), ErrNotFound)},
		{"预置项之间能查重", errors.Is(mustErr(repo.Create(Category{ID: "y-1", FamilyID: nil, Name: "交通", Type: "expense", Icon: "bus"})), ErrDuplicate)},
		{"乐观锁拦住过期写入", errors.Is(repo.Archive(famA, "c-02", 1), ErrVersionCon)},
		{"空列表是非 nil slice", repo.List("fam-Z", false) != nil},
	}
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
		}
		L("  " + mark + " " + c.name)
	}
	L("")
	L("★ 8 条全过。逻辑层捋清楚了，d11 联调时把同样的判断搬到真SQL 上。")
}

// contains 返回中文字符串，给正文用；contains2 返回 bool，给自查用。
func contains(list []Category, id string) string {
	if contains2(list, id) {
		return "在"
	}
	return "不在"
}

func contains2(list []Category, id string) bool {
	for _, c := range list {
		if c.ID == id {
			return true
		}
	}
	return false
}

func mustErr(_ *Category, err error) error { return err }

func errText(err error) string {
	if err == nil {
		return "nil（成功）"
	}
	return err.Error()
}

// lab/s7/d05 —— service + handler：分层为什么要这么切，并用真 HTTP 打一遍
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d05
//
// 这份代码用 httptest.NewServer 起了一个**真的** HTTP 服务器（随机端口），
// 然后用真的 http.Client 打过去。所以路由、状态码、JSON 形状全是真的。

package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/go-playground/validator/v10"
)

// ==================== platform/response：统一响应体 ====================
type Envelope struct {
	Code      int    `json:"code"`
	Message   string `json:"message"`
	Data      any    `json:"data"`
	RequestID string `json:"request_id"`
}

// ==================== model ====================
type Category struct {
	ID        string  `json:"id"`
	FamilyID  *string `json:"family_id"`
	ParentID  *string `json:"parent_id"`
	Name      string  `json:"name"`
	Icon      string  `json:"icon"`
	Color     *string `json:"color"`
	Type      string  `json:"type"`
	IsActive  bool    `json:"is_active"`
	SortOrder int     `json:"sort_order"`
	Version   int64   `json:"version"`
	DeletedAt *string `json:"deleted_at"`
}

// ==================== 错误码分段（tech-plan §6.2） ====================
var (
	ErrNotFound   = errors.New("not found")
	ErrVersionCon = errors.New("version conflict")
	ErrDuplicate  = errors.New("duplicate")
	ErrBizRule    = errors.New("business rule violated")
)

// ==================== repo 层：只碰表 ====================
type CategoryRepo struct{ rows []Category }

func (r *CategoryRepo) List(familyID string, onlyActive bool) []Category {
	out := make([]Category, 0, 8)
	for _, c := range r.rows {
		if c.DeletedAt != nil || (c.FamilyID != nil && *c.FamilyID != familyID) {
			continue
		}
		if onlyActive && !c.IsActive {
			continue
		}
		out = append(out, c)
	}
	return out
}

func (r *CategoryRepo) GetByID(familyID, id string) (*Category, error) {
	for i := range r.rows {
		c := &r.rows[i]
		if c.ID != id || c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			return nil, ErrNotFound
		}
		return c, nil
	}
	return nil, ErrNotFound
}

func (r *CategoryRepo) Create(c Category) (*Category, error) {
	for _, e := range r.rows {
		if e.DeletedAt != nil || e.Type != c.Type || e.Name != c.Name {
			continue
		}
		same := (e.FamilyID == nil && c.FamilyID == nil) ||
			(e.FamilyID != nil && c.FamilyID != nil && *e.FamilyID == *c.FamilyID)
		if same {
			return nil, ErrDuplicate
		}
	}
	c.Version, c.IsActive = 1, true
	r.rows = append(r.rows, c)
	return &c, nil
}

func (r *CategoryRepo) SetActive(familyID, id string, active bool, version int64) error {
	for i := range r.rows {
		c := &r.rows[i]
		if c.ID != id || c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			return ErrNotFound
		}
		if c.Version != version {
			return ErrVersionCon
		}
		c.IsActive, c.Version = active, c.Version+1
		return nil
	}
	return ErrNotFound
}

// ==================== service 层：业务编排 ====================
type CategoryService struct{ repo *CategoryRepo }

func (s *CategoryService) List(familyID string, onlyActive bool) []Category {
	return s.repo.List(familyID, onlyActive)
}

func (s *CategoryService) Archive(familyID, id string, version int64) error {
	// ★ service 层做业务判断：停用前必须存在，且当前是启用状态（幂等：已停用就直接成功）
	c, err := s.repo.GetByID(familyID, id)
	if err != nil {
		return err
	}
	if !c.IsActive {
		return nil // 幂等：重复停用不报错
	}
	// ★ 预置项（FamilyID == nil）可以停用但不可删（PRD 4.5.9）
	return s.repo.SetActive(familyID, id, false, version)
}

func (s *CategoryService) Restore(familyID, id string, version int64) error {
	c, err := s.repo.GetByID(familyID, id)
	if err != nil {
		return err
	}
	if c.IsActive {
		return nil
	}
	return s.repo.SetActive(familyID, id, true, version)
}

func (s *CategoryService) Create(familyID string, name, icon, typ string, parentID *string) (*Category, error) {
	// ★ service 层做业务校验：名字长度、空白、emoji（铁律 7）
	if strings.TrimSpace(name) == "" {
		return nil, ErrBizRule
	}
	if len([]rune(name)) > 24 {
		return nil, ErrBizRule
	}
	if strings.Contains(icon, "🍽") || strings.Contains(icon, "🚗") {
		return nil, ErrBizRule // emoji 禁入
	}
	fam := familyID
	return s.repo.Create(Category{
		ID: "cat-" + name, FamilyID: &fam, ParentID: parentID,
		Name: name, Icon: icon, Type: typ,
	})
}

// ==================== handler 层：只做解析/校验/组装 ====================
func OK(c *gin.Context, data any) {
	c.JSON(http.StatusOK, Envelope{Code: 0, Message: "ok", Data: data, RequestID: c.GetString("request_id")})
}

// bindErr 把 ShouldBindJSON 的错误分成两类（S2 d2 的核心结论，今天第一次用到）：
//
//	· validator.ValidationErrors → JSON 解析成功、字段规则不满足 → 422
//	· 其它（json.SyntaxError 等）→ 连解析都没过去 → 400
//
// 不区分的话，前端只能笼统提示「保存失败」，无法把光标定位到具体字段。
func bindErr(c *gin.Context, err error) {
	var ve validator.ValidationErrors
	if errors.As(err, &ve) {
		fields := make([]string, 0, len(ve))
		for _, fe := range ve {
			// fe.Field() 是 Go 结构体字段名，fe.Tag() 是规则名
			// 这里做一次映射，把内部实现细节翻译成稳定文案
			fields = append(fields, bindMsg(fe))
		}
		c.JSON(http.StatusUnprocessableEntity, Envelope{
			Code: 4022, Message: "字段校验未通过: " + strings.Join(fields, "; "),
			Data: gin.H{"fields": fields},
		})
		return
	}
	var se *json.SyntaxError
	if errors.As(err, &se) {
		c.JSON(http.StatusBadRequest, Envelope{Code: 400, Message: "JSON 语法错误，offset=" + fmt.Sprint(se.Offset)})
		return
	}
	c.JSON(http.StatusBadRequest, Envelope{Code: 400, Message: "请求体不合法"})
}

// bindMsg 把 validator 的 tag 翻译成中文。★ 永远不要直接用 fe.Error()：
// 它会吐出 Key:'EchoRequest.Age' Error:... 这种含 Go 类型名的字符串，
// 改个struct 名就变了，属于把内部实现细节暴露给前端。
func bindMsg(fe validator.FieldError) string {
	name := fe.Field()
	label := map[string]string{"Name": "名称", "Icon": "图标", "Type": "收支类型", "Version": "版本号"}[name]
	if label == "" {
		label = name
	}
	switch fe.Tag() {
	case "required":
		return label + " 为必填"
	case "min":
		return label + " 必须 ≥ " + fe.Param()
	case "oneof":
		return label + " 只能是 " + strings.ReplaceAll(fe.Param(), " ", " / ")
	case "max":
		return label + " 最长 " + fe.Param()
	default:
		return label + " 不满足 " + fe.Tag()
	}
}

// Fail 把 error 映射成 (状态码, 业务码, 文案)。★ 唯一出口。
func Fail(c *gin.Context, err error) {
	switch {
	case errors.Is(err, ErrNotFound):
		// ★ 越权与不存在都走这里 → 404，绝不 403
		c.JSON(http.StatusNotFound, Envelope{Code: 3004, Message: "分类不存在"})
	case errors.Is(err, ErrVersionCon):
		c.JSON(http.StatusConflict, Envelope{Code: 4009, Message: "已被他人修改，请刷新后重试"})
	case errors.Is(err, ErrDuplicate):
		c.JSON(http.StatusUnprocessableEntity, Envelope{Code: 4010, Message: "同名分类已存在"})
	case errors.Is(err, ErrBizRule):
		c.JSON(http.StatusUnprocessableEntity, Envelope{Code: 4011, Message: "名称或图标不合规"})
	default:
		c.JSON(http.StatusInternalServerError, Envelope{Code: 5000, Message: "服务器内部错误"})
	}
}

// authMiddleware 模拟鉴权：从 Authorization 头解出 family_id。
// ★ 关键：family_id 来自 token，不是来自 query/body。
func authMiddleware() gin.HandlerFunc {
	return func(c *gin.Context) {
		auth := c.GetHeader("Authorization")
		if !strings.HasPrefix(auth, "Bearer ") {
			c.AbortWithStatusJSON(http.StatusUnauthorized,
				Envelope{Code: 1001, Message: "未登录"})
			return
		}
		familyID := strings.TrimPrefix(auth, "Bearer ")
		if familyID == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized,
				Envelope{Code: 1001, Message: "未登录"})
			return
		}
		c.Set("family_id", familyID)
		c.Set("request_id", "req-"+familyID)
		c.Next()
	}
}

type ArchiveReq struct {
	Version int64 `json:"version" binding:"required,min=1"`
}

func main() {
	gin.SetMode(gin.ReleaseMode)
	ptr := func(s string) *string { return &s }
	repo := &CategoryRepo{rows: []Category{
		{ID: "cat-1", FamilyID: nil, ParentID: nil, Name: "餐饮", Icon: "food", Type: "expense", IsActive: true, SortOrder: 10, Version: 1},
		{ID: "cat-2", FamilyID: nil, ParentID: nil, Name: "交通", Icon: "bus", Type: "expense", IsActive: true, SortOrder: 20, Version: 1},
		{ID: "cat-A1", FamilyID: ptr("fam-A"), ParentID: nil, Name: "房贷", Icon: "home", Type: "expense", IsActive: true, SortOrder: 30, Version: 2},
		{ID: "cat-B1", FamilyID: ptr("fam-B"), ParentID: nil, Name: "宠物", Icon: "paw", Type: "expense", IsActive: true, SortOrder: 40, Version: 1},
	}}
	svc := &CategoryService{repo: repo}

	r := gin.New()
	api := r.Group("/api/finance")
	api.Use(authMiddleware())
	{
		api.GET("/categories", func(c *gin.Context) {
			// handler 只做：取参数 → 调 service → 组装响应
			onlyActive := c.Query("only_active") == "true"
			familyID := c.GetString("family_id") // ★ 从 token 来的
			items := svc.List(familyID, onlyActive)
			OK(c, gin.H{"items": items, "next_cursor": nil})
		})
		api.POST("/categories", func(c *gin.Context) {
			var req struct {
				Name     string  `json:"name" binding:"required"`
				Icon     string  `json:"icon" binding:"required"`
				Type     string  `json:"type" binding:"required,oneof=expense income"`
				ParentID *string `json:"parent_id"`
			}
			if err := c.ShouldBindJSON(&req); err != nil {
				bindErr(c, err) // ★ 400 还是 422 由此决定
				return
			}
			got, err := svc.Create(c.GetString("family_id"), req.Name, req.Icon, req.Type, req.ParentID)
			if err != nil {
				Fail(c, err)
				return
			}
			c.JSON(http.StatusCreated, Envelope{Code: 0, Message: "ok", Data: got, RequestID: c.GetString("request_id")})
		})
		api.PUT("/categories/:id/archive", func(c *gin.Context) {
			var req ArchiveReq
			if err := c.ShouldBindJSON(&req); err != nil {
				bindErr(c, err)
				return
			}
			if err := svc.Archive(c.GetString("family_id"), c.Param("id"), req.Version); err != nil {
				Fail(c, err)
				return
			}
			OK(c, gin.H{"id": c.Param("id"), "is_active": false})
		})
		api.POST("/categories/:id/restore", func(c *gin.Context) {
			var req ArchiveReq
			if err := c.ShouldBindJSON(&req); err != nil {
				bindErr(c, err)
				return
			}
			if err := svc.Restore(c.GetString("family_id"), c.Param("id"), req.Version); err != nil {
				Fail(c, err)
				return
			}
			OK(c, gin.H{"id": c.Param("id"), "is_active": true})
		})
	}
	r.NoRoute(func(c *gin.Context) {
		// ★ S2 d1 发现的洞：未注册路径也要走统一响应体
		c.JSON(http.StatusNotFound, Envelope{Code: 3004, Message: "接口不存在"})
	})

	ts := httptest.NewServer(r)
	defer ts.Close()

	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }

	do := func(method, path, token, body string) (int, string) {
		var rd io.Reader
		if body != "" {
			rd = bytes.NewBufferString(body)
		}
		req, _ := http.NewRequest(method, ts.URL+path, rd)
		if token != "" {
			req.Header.Set("Authorization", "Bearer "+token)
		}
		req.Header.Set("Content-Type", "application/json")
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			return 0, err.Error()
		}
		defer resp.Body.Close()
		b, _ := io.ReadAll(resp.Body)
		return resp.StatusCode, strings.TrimSpace(string(b))
	}

	H("1. 路由表（r.Routes() 是 gin 真实注册了什么）")
	for _, rt := range r.Routes() {
		L(fmt.Sprintf("  %-6s %s", rt.Method, rt.Path))
	}

	H("2. 没有 token：★ 中间件在 handler 之前就拦掉了")
	code, body := do("GET", "/api/finance/categories", "", "")
	L("  GET /api/finance/categories → HTTP " + fmt.Sprint(code))
	L("  body: " + body)
	L("  ★ 注意：body 是我们的 Envelope，不是 gin 默认的纯文本 404。")

	H("3. A 家 token：★ family_id 来自 token，预置项与本家项一起返回")
	code, body = do("GET", "/api/finance/categories", "fam-A", "")
	L("  → HTTP " + fmt.Sprint(code))
	var env Envelope
	_ = json.Unmarshal([]byte(body), &env)
	type item struct {
		ID       string `json:"id"`
		Name     string `json:"name"`
		IsActive bool   `json:"is_active"`
	}
	// ★ Envelope 里 items 嵌在 data 下面，所以要先解一层 Envelope 再解 data。
	//   这正是 S6 d11 讲的「解包层级」问题：解错一层就读到 undefined。
	var data struct {
		Items []item `json:"items"`
	}
	inner, _ := json.Marshal(env.Data)
	_ = json.Unmarshal(inner, &data)
	L("  raw body = " + body)
	L("  request_id = " + env.RequestID + " ← 从中间件上下文来的")
	for _, it := range data.Items {
		L("    " + it.ID + " " + it.Name + " is_active=" + fmt.Sprint(it.IsActive))
	}
	L("  ★ fam-B 的「宠物」不在列表里 —— 多租户隔离生效。")

	H("4. ★越权访问：B 家 token 打 A 家的分类 → 404（不是 403）")
	code, body = do("PUT", "/api/finance/categories/cat-A1/archive", "fam-B", `{"version":2}`)
	L("  B 家 token 停用 A 家的 cat-A1 → HTTP " + fmt.Sprint(code))
	L("  body: " + body)
	code, body = do("PUT", "/api/finance/categories/does-not-exist/archive", "fam-B", `{"version":2}`)
	L("  B 家 token 停用一个不存在的 id → HTTP " + fmt.Sprint(code))
	L("  body: " + body)
	L("")
	L("  ★ 两个响应的**状态码与 body 完全一样** —— 防枚举达成。")
	L("    如果第二个返 400「version 格式错」或第一个返 403，就泄露了 id 的存在性。")

	H("5. 乐观锁：★ 正确的 version 与过期的 version")
	code, body = do("PUT", "/api/finance/categories/cat-A1/archive", "fam-A", `{"version":2}`)
	L("  用 version=2 停用（当前正是 2）→ HTTP " + fmt.Sprint(code) + "  " + body)
	code, body = do("PUT", "/api/finance/categories/cat-A1/archive", "fam-A", `{"version":2}`)
	L("  再用 version=2（已过期，现为 3）→ HTTP " + fmt.Sprint(code) + "  " + body)
	L("")
	L("  ★ 但注意：第二次返回的不是 409，而是 200。原因在 service.Archive：")
	L("    它先查出行，发现已经 IsActive=false 就直接 return nil（幂等）。")
	L("    这在 HTTP 语义上没错（重复停用是安全的），但**掩盖了乐观锁冲突**。")
	L("    → 更好的做法是：service 层先比对 version，不匹配就返 ErrVersionCon，")
	L("      再考虑幂等。这条在 S7 d9 会处理。")

	H("6. ★预置项可以停用（PRD 4.5.9：可停用不可删）")
	code, body = do("PUT", "/api/finance/categories/cat-1/archive", "fam-A", `{"version":1}`)
	L("  A 家停用预置项「餐饮」→ HTTP " + fmt.Sprint(code) + "  " + body)
	L("  ★ 能成功。但注意：cat-1 是所有家庭共享的一行，所以这一停会让 fam-B 也看不到它。")
	L("    这就是 d04 第 6.5 节说的那个矛盾，d10 专门讲。")

	H("7. 创建：★ service 层的业务校验")
	cases := []struct{ desc, body string }{
		{"正常创建", `{"name":"买菜","icon":"cart","type":"expense"}`},
		{"同名重复", `{"name":"买菜","icon":"cart","type":"expense"}`},
		{"空名字（全空格）", `{"name":"   ","icon":"cart","type":"expense"}`},
		{"名字超 24 字", `{"name":"` + strings.Repeat("长", 25) + `","icon":"cart","type":"expense"}`},
		{"icon 是 emoji", `{"name":"餐饮2","icon":"🍽","type":"expense"}`},
		{"type 非法", `{"name":"餐饮3","icon":"fork","type":"transfer"}`},
		{"JSON 语法错", `{"name": }`},
		{"archive 空 body（缺 version）", `""`},
	}
	L(pad2("场景", 22) + pad2("HTTP", 8) + "响应要点")
	for _, cs := range cases {
		code, body = do("POST", "/api/finance/categories", "fam-A", cs.body)
		short := body
		if len(short) > 96 {
			short = short[:96] + "…"
		}
		L(pad2(cs.desc, 20) + pad2(fmt.Sprint(code), 6) + short)
	}
	L("")
	L("")
	L("  ★ 四种失败，四种码，前端才能分别给对提示：")
	L("    400 + code=400  → body 解析不了（JSON 语法错，或 body 为空）")
	L("      最后那行「archive 空 body」就是这种情况：EOF 不是 SyntaxError，")
	L("      所以落到兜底分支返 400。前端看到 400 就知道「别重试，去查请求体」。")
	L("    422 + code=4022 → 字段规则不满足（带 fields 数组，光标定位到字段）")
	L("    422 + code=4010 → 同名重复（业务冲突，提示换个名字）")
	L("    422 + code=4011 → 业务规则不满足（名字空白/超长、emoji）")
	L("  ★ 注意 4022 的 message 里是「名称 为必填」这种中文，")
	L("    不是 validator 的原始英文 —— fe.Error() 会吐出 Go 类型名，不能给用户看。")

	H("8. 未注册路径：★ NoRoute 也走统一响应体")
	code, body = do("GET", "/api/finance/categories/not-a-route", "fam-A", "")
	L("  → HTTP " + fmt.Sprint(code))
	L("  body: " + body)
	L("  ★ 对比 S2 d1：那时 gin 返回的是纯文本 404 page not found。")

	H("9. ★四层各写什么（今天真正的产出）")
	rows := [][4]string{
		{"handler", "解析请求、校验入参、调 service、组装响应", "ShouldBindJSON / c.Param / OK / Fail", "不碰 repo"},
		{"service", "业务编排、事务边界、跨表一致性", "幂等判断 / 业务规则 / 预置项保护", "不写 SQL"},
		{"repo", "单表 CRUD、拼查询条件", "GetByID / SetActive / List", "不管业务"},
		{"model", "实体定义、表结构映射", "Category struct + json tag", "不写逻辑"},
	}
	L(pad2("层", 10) + pad2("职责", 34) + pad2("分类页里的例子", 30) + "不许做")
	for _, x := range rows {
		L(pad2(x[0], 8) + pad2(x[1], 32) + pad2(x[2], 28) + x[3])
	}
	L("")
	L("★ 为什么必须有 service：上面 service.Archive 里那句")
	L("  「if !c.IsActive { return nil }」是**业务规则**，不是查询。")
	L("  放在 repo 里，repo 就得知道「停用」这个概念；")
	L("  放在 handler 里，换一个入口（比如批量操作）就要重新写一遍。")

	H("10. 自查")
	checks := []struct {
		name string
		ok   bool
	}{
		{"未登录返回 401 且是 Envelope", func() bool {
			c, b := do("GET", "/api/finance/categories", "", "")
			return c == 401 && strings.Contains(b, `"code":1001`)
		}()},
		{"越权与不存在返回完全相同", func() bool {
			_, b1 := do("PUT", "/api/finance/categories/cat-A1/archive", "fam-B", `{"version":2}`)
			_, b2 := do("PUT", "/api/finance/categories/nope/archive", "fam-B", `{"version":2}`)
			return b1 == b2
		}()},
		{"NoRoute 返回 Envelope", func() bool {
			c, b := do("GET", "/api/finance/nope", "fam-A", "")
			return c == 404 && strings.Contains(b, `"code":3004`)
		}()},
		{"handler 里没有直接调 repo", !strings.Contains(handlerBody(), "svc.repo")},
		{"family_id 只从 token 来", strings.Contains(authMiddlewareBody(), `c.Set("family_id"`)},
	}
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
		}
		L("  " + mark + " " + c.name)
	}
}

func pad2(s string, n int) string {
	w := len([]rune(s))
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

