const VUE = `<script setup lang="ts">
import { ref, computed, onShow, onLoad } from 'vue'
import { request, RequestError } from '@/utils/request'

// 与 d02 契约里的 Category 一一对应
interface Category {
  id: string
  family_id: string | null   // null = 预置字典项
  parent_id: string | null   // null = 一级分类
  name: string
  icon: string
  color: string | null
  type: 'expense' | 'income'
  is_active: boolean
  sort_order: number
  version: number
}

interface CategoryNode extends Category {
  children: CategoryNode[]     // ★ 前端自己算出来的，不在后端响应里
}

const rows = ref<Category[]>([])       // 整体替换 → ref
const loading = ref(false)             // 整体替换 → ref
const keyword = ref('')                // 整体替换 → ref
const showInactive = ref(true)         // 整体替换 → ref
const expanded = ref<Record<string, boolean>>({})  // 展开态：改字段 → reactive 风格

// ★ 两级树由前端拼出来。契约里返回的是扁平数组，parent_id 表达层级。
//   为什么不放后端拼：报表图例、筛选 chips、记账选择器要同一份顺序，
//   顺序由 sort_order 决定；而「是否展开」是纯 UI 状态，后端不知道。
function buildTree(list: Category[]): CategoryNode[] {
  const byId = new Map<string, CategoryNode>()
  for (const c of list) byId.set(c.id, { ...c, children: [] })
  const roots: CategoryNode[] = []
  for (const node of byId.values()) {
    if (node.parent_id && byId.has(node.parent_id)) {
      byId.get(node.parent_id)!.children.push(node)
    } else {
      roots.push(node)                 // parent_id 为空 → 一级
    }
  }
  const byOrder = (a: CategoryNode, b: CategoryNode) => a.sort_order - b.sort_order
  roots.sort(byOrder)
  roots.forEach((r) => r.children.sort(byOrder))
  return roots
}

const filtered = computed(() => {
  const k = keyword.value.trim()
  let list = rows.value
  // ★ 列表页要能看到停用项（PRD 4.5.9），开关只是把它灰显/隐藏
