  if (!k) return list
  // 命中自身或父级名都算命中（S7 d14 需求1 的正确写法）
  const nameOf = new Map(rows.value.map((c) => [c.id, c.name]))
  const hit = (c: Category) => c.name.includes(k) ||
    (c.parent_id && nameOf.get(c.parent_id)?.includes(k))
  return list.filter(hit)
})

const tree = computed(() => buildTree(filtered.value))

const isOpen = (id: string) => expanded.value[id] !== false   // 默认展开

function toggle(id: string) {
  expanded.value[id] = !isOpen(id)     // ★ 直接改字段
}

async function fetchCategories() {
  loading.value = true
  try {
    const body = await request<{ items: Category[]; next_cursor: null }>(
      '/api/finance/categories'
    )
    // ★ 出口契约是裸响应体，直接读 body.items，不要再 .data 剥一层
    rows.value = body.items ?? []
