// pretty 把渲染出来的 HTML 整理成缩进结构，保留 v-if/v-for 留下的注释锚点。
// 这些注释在真实页面里也看得到（它们是 Vue 的插入锚点），不是渲染错误。
function pretty(html) {
  let s = html
    .replace(/<!--\[-->/g, '\n<<<')
    .replace(/<!--\]-->/g, '')
    .replace(/<!--v-if-->/g, ' [v-if 占位]')
  const out = []
  let depth = 0
  // 逐个标签扫一遍，自己维护缩进
  const re = /<(\/?)([a-zA-Z-]+)([^>]*)>|([^<]+)/g
  let m
  const stack = []
  while ((m = re.exec(s)) !== null) {
    const [, closing, tag, attrs, text] = m
    if (text !== undefined) {
      const t = text.trim()
      if (t) out.push('  '.repeat(stack.length) + '"' + t + '"')
      continue
    }
    const selfClose = /\/$/.test(attrs)
    if (closing) {
      stack.pop()
    } else {
      const a = attrs.trim().replace(/\s+/g, ' ')
      out.push('  '.repeat(stack.length) + '<' + tag + (a ? ' ' + a : '') + '>')
      if (!selfClose) stack.push(tag)
    }
  }
  return out.join('\n')
}
await main()

