  name: '',
  icon: 'food',
  color: '#FF6B35',
  type: 'expense',
  parent_id: '',
})

const submitting = ref(false)
const fieldErrors = reactive({})     // 服务端 422 带回来的字段级错误
const options = ref([])               // 一级分类列表，作为 parent 的候选

// ★ 校验：前端先做一遍，减少无谓往返；但服务端校验才是权威（S7 d5 实测过）
const localError = computed(() => {
  const e = {}
  if (!form.name.trim()) e.name = '名称不能为空'
  else if (form.name.trim().length > 24) e.name = '名称最长 24 个字'
  if (!form.icon.trim()) e.icon = '必须选一个图标'
  return e
})
const canSubmit = computed(() => Object.keys(localError.value).length === 0 && !submitting.value)

function fill(c) {                    // 编辑时把数据灌进 form
  form.name = c.name
  form.icon = c.icon
  form.color = c.color || '#FF6B35'
  form.type = c.type
  form.parent_id = c.parent_id || ''
  Object.keys(fieldErrors).forEach((k) => delete fieldErrors[k])   // 清掉上次的错误
}

async function submit() {
  if (!canSubmit.value) return
  submitting.value = true
  try {
    const payload = {
      name: form.name.trim(),
      icon: form.icon,
      color: form.color || undefined,
      type: form.type,
      parent_id: form.parent_id || undefined,
    }
    if (editingId.value) {
      // ★ 编辑必须带 version —— 没有乐观锁，两个人同时改会静默覆盖
      const cur = options.value.find((o) => o.id === editingId.value)
      await request('PUT', '/api/finance/categories/' + editingId.value,
        { ...payload, version: cur ? cur.version : 1 })
    } else {
      await request('POST', '/api/finance/categories', payload)
    }
    uni.navigateBack()
  } catch (e) {
    if (e instanceof RequestError && e.status === 422) {
      // ★ 服务端把字段级错误放在 data.fields，逐个挂到对应输入框
      const fields = (e.body && e.body.data && e.body.data.fields) || []
      fields.forEach((f) => { fieldErrors[nameOf(f)] = f })
    }
  } finally {
    submitting.value = false
  }
}

const nameOf = (msg) => msg.includes('名称') ? 'name' : 'icon'

onLoad((opts) => {
  if (opts && opts.id) editingId.value = opts.id
})
