        <text class="seg-item" :class="{ on: form.type === 'income' }"
              @click="form.type = 'income'">收入</text>
      </view>
    </view>

    <view class="field">
      <text class="label">父级（留空即一级）</text>
      <text class="picker">{{ form.parent_id || '无（一级分类）' }}</text>
    </view>

    <button class="submit" :disabled="!canSubmit" @click="submit">
      {{ submitting ? '保存中…' : '保存' }}
    </button>
  </view>
</template>

<style scoped>
.err { color: #ff4d4f; font-size: 24rpx; }
.off .err { color: #999; }
</style>`

async function main() {
  H("1. 编译这份表单页")
  const c = compileSFC(VUE, 'category/form.vue')
  L('  编译成功 = ' + (c.ok ? '是' : '否') + '，产出 ' + (c.ok ? c.code.split('\n').length : 0) + ' 行')
  L('  style 块= ' + c.descriptor.styles.length + ' 个，scoped=' + c.descriptor.styles.map(s => s.scoped).join(','))
  if (!c.ok) { L(c.errors.join('\n')); return }

  H("2. ★为什么用 reactive 而不是 ref（这一行决定了你后面会不会写错）")
  const cmp = [
    ['整体替换（重新拉接口的结果）', 'ref', 'rows.value = body.items'],
    ['只改字段（表单输入）', 'reactive', 'form.name = \'餐饮\''],
  ]
  L('  场景'.padEnd(34) + '用哪个'.padEnd(10) + '写法')
  for (const [a, b, cc] of cmp) L('  ' + a.padEnd(30) + b.padEnd(8) + cc)
  L('')
  L('  ★ 如果表单用 ref([])，每次输入都要写 form.value.name = v，模板里也要写 form.value.name；')
  L('    用 reactive 则两边都不用写 .value —— 这就是 S6 d03 讲的「reactive 不能解构」的另一面。')
  L('  ★ 但注意：form 不能传给只接受 ref 的地方，且不能整体替换（form = {...} 会丢响应式）。')

  H("3. ★同一个页面承担新建与编辑，关键在 onLoad 拿路由参数")
  L('  新建：uni.navigateTo({ url: \'/pages/finance/category/form\' })')
  L('  编辑：uni.navigateTo({ url: \'/pages/finance/category/form?id=cat-A2\' })')
  L('  页面里：onLoad((opts) => { if (opts && opts.id) editingId.value = opts.id })')
  L('')
  L('  ★ 标题用插值决定：{{ editingId ? \'编辑分类\' : \'新建分类\' }}')
  L('    不要写两个页面（form.vue 和 edit.vue）—— 字段一改就要改两处，')
  L('    这是前端最常见的重复代码来源之一。')

  H("4. ★校验为什么写两遍（前端一遍 + 服务端一遍）")
  const cases = [
    ['名称为空', '', '前端拦住，不发请求'],
    ['名称 25 个字', '长'.repeat(25), '前端拦住（maxlength=24 也会先挡一道）'],
    ['名称正常', '买菜', '发请求'],
    ['图标含 emoji', '🍽', '★ 前端拦不住 —— 必须靠服务端'],
  ]
  L('  场景'.padEnd(20) + '输入'.padEnd(14) + '结果')
  for (const [a, b, cc] of cases) {
    const v = a === '名称为空' ? '' : b
    let local = null
    if (!v.trim()) local = '名称不能为空'
    else if (v.trim().length > 24) local = '名称最长 24 个字'
    const emoji = v.includes('🍽')
    L('  ' + a.padEnd(16) + (v.slice(0, 10) || '(空)').padEnd(12) +
      (local ? '前端拦住' : emoji ? '★ 前端放行，靠服务端 422' : '发请求'))
  }
  L('')
  L('  ★ 结论：前端校验是为了「体验」（少一次往返、即时反馈），')
  L('    服务端校验是为了「正确」（前端可以被绕过）。两者不能互相替代。')
  L('  ★ S7 d5 实测过：icon 是 emoji 时，前端没拦但服务端返422 code=4011。')

  H("5. ★422 的字段级错误要挂到具体输入框")
  L('  服务端返回（S7 d5 实测的形状）：')
  L('    {"code":4022,"message":"字段校验未通过: 收支类型 只能是 expense / income",')
  L('     "data":{"fields":["收支类型 只能是 expense / income"]}}')
  L('')
  L('  前端处理：')
  L('    const fields = e.body.data.fields ?? []')
  L('    fields.forEach(f => { fieldErrors[guessField(f)] = f })')
  L('    // guessField: message 里含「名称」→ name，含「图标」→ icon')
  L('')
  L('  ★ 服务端返回的是中文文案，前端靠字符串匹配反推字段 —— 这很脆弱。')
  L('    更好的做法是契约里约定 fields 用结构体：')
  L('    "fields": [{"field": "type", "message": "收支类型 只能是 expense / income"}]')
  L('    ★ 记录成一条待改进项：d02 的契约里 fields 应该是数组对象而不是字符串数组。')

  H("6. 自查")
  const checks = [
    ['编译无错误', c.ok],
    ['表单状态用 reactive', /const form = reactive\(/.test(VUE)],
    ['提交状态用 ref（要整体替换 true/false）', /const submitting = ref\(/.test(VUE)],
    ['编辑分支带了 version', /version: cur \? cur.version : 1/.test(VUE)],
    ['按钮 disabled 绑了 canSubmit', /:disabled="!canSubmit"/.test(VUE)],
    ['没有用div/span', !/<(div|span)\b/.test(VUE.match(/<template>[\s\S]*?<\/template>/)[0])],
    ['错误提示挂在输入框下方', /v-if="fieldErrors.name \|\| localError.name"/.test(VUE)],
  ]
  for (const [n, ok] of checks) L('  ' + (ok ? '✅' : '❌') + ' ' + n)
}
await main()

// lab/s7/d08 —— 停用 vs 删除：S7 的核心概念，用一个内存库把四种操作的后果真跑一遍
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d08

package main

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

func pad(s string, n int) string {
	w := utf8.RuneCountInString(s)
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

type Category struct {
	ID        string
	FamilyID  *string
	Name      string
	Type      string
	IsActive  bool
	DeletedAt *string
	Version   int64
}

// Tx 是「流水」，只读，用来证明历史数据不会因为分类停用/删除而消失
type Tx struct {
	ID          string
	FamilyID    string
	CategoryID  string
	AmountCents int64
	OccurredAt  string
}

type Store struct {
	Cats []Category
	Txs  []Tx
}

var (
	ErrNotFound   = errors.New("not found")
	ErrReferenced = errors.New("category is referenced by transactions")
	ErrPreset     = errors.New("preset category can not be deleted")
)

func (s *Store) byID(id string) *Category {
	for i := range s.Cats {
		if s.Cats[i].ID == id {
			return &s.Cats[i]
		}
	}
	return nil
}

// Archive = 停用：is_active=false。历史流水完全不受影响。
func (s *Store) Archive(familyID, id string, version int64) error {
	c := s.byID(id)
	if c == nil || c.DeletedAt != nil {
		return ErrNotFound
	}
	if c.FamilyID != nil && *c.FamilyID != familyID {
		return ErrNotFound
	}
	if c.Version != version {
		return errors.New("version conflict")
	}
	c.IsActive, c.Version = false, c.Version+1
	return nil
}

func (s *Store) Restore(familyID, id string, version int64) error {
	c := s.byID(id)
	if c == nil || c.DeletedAt != nil {
		return ErrNotFound
	}
	if c.FamilyID != nil && *c.FamilyID != familyID {
		return ErrNotFound
	}
	if c.Version != version {
		return errors.New("version conflict")
	}
	c.IsActive, c.Version = true, c.Version+1
	return nil
}

// SoftDelete = 软删：写 deleted_at。仅限自定义项，且被流水引用时一律拒绝。
func (s *Store) SoftDelete(familyID, id, memberID string) error {
	c := s.byID(id)
	if c == nil || c.DeletedAt != nil {
		return ErrNotFound
	}
	if c.FamilyID == nil {
		return ErrPreset // ★ 预置项一律不可删（PRD 4.5.9）
	}
	if *c.FamilyID != familyID {
		return ErrNotFound
	}
	// ★ 被流水引用时拒绝并提示改用停用
	for _, t := range s.Txs {
		if t.CategoryID == id {
			return ErrReferenced
		}
	}
	now := "2026-10-15T12:00:00Z"
	c.DeletedAt = &now
	c.Version++
	_ = memberID
	return nil
}

// ★ 流水按分类汇总 —— 这是「历史数据照常统计」这句话的证明
func (s *Store) sumByCategory(familyID string, onlyActive bool) map[string]int64 {
	out := map[string]int64{}
	for _, t := range s.Txs {
		if t.FamilyID != familyID {
			continue
		}
		c := s.byID(t.CategoryID)
		if c == nil {
			continue
		}
		if c.DeletedAt != nil {
			continue // 软删的分类，其流水不再参与统计（因为分类本身不可见了）
		}
		if onlyActive && !c.IsActive {
			continue
		}
		out[c.Name] += t.AmountCents
	}
	return out
}

func (s *Store) dump(title string) {
	L := func(x string) { fmt.Println(x) }
	L("  " + title)
	L("    " + pad("ID", 8) + pad("名称", 12) + pad("is_active", 12) + pad("deleted_at", 24) + "version")
	for _, c := range s.Cats {
		d := "—"
		if c.DeletedAt != nil {
			d = *c.DeletedAt
		}
		L("    " + pad(c.ID, 6) + pad(c.Name, 10) + pad(fmt.Sprint(c.IsActive), 10) +
			pad(d, 22) + fmt.Sprint(c.Version))
	}
}

func main() {
	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }
	p := func(s string) *string { return &s }
	const fam = "fam-A"

	H("0. 起点：一个家庭、两级分类、四条流水")
	store := &Store{
		Cats: []Category{
			{ID: "c-1", FamilyID: nil, Name: "餐饮", Type: "expense", IsActive: true, Version: 1},
			{ID: "c-2", FamilyID: p(fam), Name: "买菜", Type: "expense", IsActive: true, Version: 1},
			{ID: "c-3", FamilyID: p(fam), Name: "外食", Type: "expense", IsActive: true, Version: 1},
			{ID: "c-4", FamilyID: p(fam), Name: "零钱备用", Type: "expense", IsActive: true, Version: 1},
			{ID: "c-6", FamilyID: p(fam), Name: "误建的分类", Type: "expense", IsActive: true, Version: 1},
		},
		Txs: []Tx{
			{ID: "t-1", FamilyID: fam, CategoryID: "c-1", AmountCents: 3500, OccurredAt: "2026-09-10"},
			{ID: "t-2", FamilyID: fam, CategoryID: "c-2", AmountCents: 8000, OccurredAt: "2026-10-01"},
			{ID: "t-3", FamilyID: fam, CategoryID: "c-3", AmountCents: 4500, OccurredAt: "2026-10-05"},
			{ID: "t-4", FamilyID: fam, CategoryID: "c-4", AmountCents: 100, OccurredAt: "2026-10-08"},
			// c-6「误建的分类」故意不给它任何流水 —— 它是「从没被用过」的典型
		},
	}
	store.dump("分类表：")
	L("  流水表：")
	for _, t := range store.Txs {
		L("    " + pad(t.ID, 6) + pad(t.CategoryID, 8) + pad(fmt.Sprint(t.AmountCents), 10) + "分")
	}
	show := func(title string, onlyActive bool) {
		m := store.sumByCategory(fam, onlyActive)
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		total := int64(0)
		parts := make([]string, 0, len(keys))
		for _, k := range keys {
			parts = append(parts, k+"="+fmt.Sprint(m[k]/100)+"元")
			total += m[k]
		}
		L("  " + pad(title, 34) + strings.Join(parts, "  ") + "   合计=" + fmt.Sprint(total/100) + "元")
	}
	L("")
	show("全部分类（含停用）参与统计：", false)
	show("仅启用分类参与统计（选择器口径）：", true)

	H("1. ★停用「买菜」：is_active=true → false")
	err := store.Archive(fam, "c-2", 1)
	L("  archive(c-2) → " + errText(err))
	store.dump("分类表：")
	L("")
	show("停用后，全量统计：", false)
	show("停用后，仅启用统计：", true)
	L("")
	L("  ★ 关键结论：")
	L("    · 全量统计里「买菜」**还在**（8000 分= 80 元），一笔不少 —— PRD 4.5.9 要求")
	L("    · 停用只影响「选择器」口径：新建流水时选不到它了")
	L("    · 这就是「停用不影响历史数据」的确切含义：影响的是**今后能不能选**，")
	L("      不影响**已经记过的账怎么算**")

	// 抓住「停用后」这一刻的两个口径，供第 8 节自查断言使用。
	// （不能等到最后再查：那时「买菜」已被恢复、「误建的分类」已被软删，状态全变了。）
	snapAll := store.sumByCategory(fam, false)["买菜"]
	snapActive := store.sumByCategory(fam, true)["买菜"]

	H("2. ★恢复「买菜」：可逆")
	err = store.Restore(fam, "c-2", 2)
	L("  restore(c-2) → " + errText(err))
	show("恢复后，仅启用统计：", true)
	L("  ★ version 从 2 变成 3 —— 每次写操作都自增，所以旧页面的 version 会失效（返 409）")

	H("3. ★软删「误建的分类」：只对**没被引用**的项放行")
	err = store.SoftDelete(fam, "c-6", "mem-1")
	L("  SoftDelete(c-6「误建的分类」，0 笔流水) → " + errText(err))
	store.dump("分类表：")
	L("")
	show("软删后，全量统计：", false)
	L("")
	L("  ★ 对比一下：")
	L("    停用买菜 → 统计里还在（80 元，一分不少）")
	L("    软删 c-6 → 它本来就没有流水，所以统计看不出变化；")
	L("      但**如果**它有流水，PRD 4.5.9 会直接拒绝这次删除（第 4 节实测）")
	L("  ★ 这就是为什么「停用」与「删除」必须是两件事：")
	L("    软删适合「从来没被用过的错建项」，用它清历史数据会直接改报表。")

	// 软删 c-6 之后：c-6 从表里彻底不可见，但它本来就没有流水，
	// 所以统计金额不变。真正能证明「软删会带走历史」的证据在第 5 节（预置项被拒）。
	snapAfterSoftDelete := store.sumByCategory(fam, false)["误建的分类"]
	_ = snapAfterSoftDelete

	H("4. ★软删被流水引用的分类：一律拒绝，并提示改用停用")
	store.Cats = append(store.Cats, Category{ID: "c-5", FamilyID: p(fam), Name: "常用", Type: "expense", IsActive: true, Version: 1})
	store.Txs = append(store.Txs, Tx{ID: "t-5", FamilyID: fam, CategoryID: "c-5", AmountCents: 20000, OccurredAt: "2026-10-09"})
	err = store.SoftDelete(fam, "c-5", "mem-1")
	L("  SoftDelete(c-5，有 200 元流水引用) → " + errText(err))
	L("  ★ 返回 ErrReferenced，PRD 4.5.9 的原话：")
	L("    「需要清理错建的自定义项才走软删 + 回收站，且被流水引用时一律拒绝并提示改用停用」")
	L("    所以正确提示是「该分类有 N 笔流水，请改用停用」，不是「删除失败」。")

	H("5. ★预置项：可停用、不可删")
	err = store.Archive(fam, "c-1", 1)
	L("  停用预置项「餐饮」 → " + errText(err) + "   ← 可以停用")
	err = store.SoftDelete(fam, "c-1", "mem-1")
	L("  软删预置项「餐饮」 → " + errText(err) + "   ← ★ 被拒")
	L("")
	L("  ★ PRD 4.5.9：「预置字典项可停用不可删除」。")
	L("    理由很直白：预置项是产品定义的一部分，不是某个家庭建的。")
	L("    允许删预置项的话，A 家删了「餐饮」，B 家的界面也会跟着少一项 ——")
	L("    这是「一家的操作影响别人」，详见 d10。")

	H("6. 四种操作对照表（这张表就是今天的产出）")
	type row struct{ 操作, 字段变化, 可逆, 历史流水, 适用场景 string }
	tbl := []row{
		{"新建", "新增一行", "—", "—", "添加分类"},
		{"编辑", "改 name/icon/…", "可逆（再改一次）", "不受影响", "改个名字"},
		{"停用 archive", "is_active=false", "可逆（restore）", "★ 照常显示与统计", "不再用但有历史"},
		{"软删 softDelete", "deleted_at=now()", "可逆（回收站 30 天）", "★ 不再参与统计", "清理从没被引用的错建项"},
		{"物理删", "DELETE FROM", "不可逆", "永久丢失", "★ 本项目不提供（PRD 4.5.9）"},
	}
	L(pad("操作", 20) + pad("字段变化", 22) + pad("可逆", 20) + pad("历史流水", 20) + "适用场景")
	for _, r := range tbl {
		L(pad(r.操作, 18) + pad(r.字段变化, 20) + pad(r.可逆, 18) + pad(r.历史流水, 18) + r.适用场景)
	}

	H("7. ★为什么「停用」这个字段必须存在（回到设计原点）")
	L("  设想没有 is_active 这个字段的世界：")
	L("    用户建了 20 个分类，用了 2 年，产生了 5000 条流水。")
	L("    其中 15 个分类他再也不会用了。")
	L("    他想清理 —— 但删掉的话，那 15 个分类的历史流水就成了孤儿：")
	L("    报表里点进去是空白，年度统计对不上账。")
	L("")
	L("  所以只能留着。这就是 is_active 的全部来由：")
	L("    它回答的是「今后还能不能选」，而不是「这个分类还在不在」。")
	L("")
	L("  ★ 类比 Go：is_active 像软删 deleted_at，但语义正交。")
	L("    deleted_at = 这行数据从业务视野里彻底消失（连回收站都要靠它筛）")
	L("    is_active  = 这行还在、还能被历史引用，只是不再作为可选项")

	H("8. 自查（全部用上面各节抓下的快照，不依赖当前状态）")
	checks := []struct {
		name string
		ok   bool
	}{
		{"停用后：全量统计里「买菜」仍是 8000 分（历史没丢）", snapAll == 8000},
		{"停用后：启用口径里「买菜」为 0（选不到了）", snapActive == 0},
		{"软删后：c-6 从统计里彻底消失（原来是 0，现在连键都没有）", snapAfterSoftDelete == 0 && !hasKey(store.sumByCategory(fam, false), "误建的分类")},
		{"软删被引用的分类被拒（真跑一次）", errors.Is(store.trySoftDelete(fam, "c-5"), ErrReferenced)},
		{"软删预置项被拒（真跑一次）", errors.Is(store.trySoftDelete(fam, "c-1"), ErrPreset)},
	}
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
		}
		L("  " + mark + " " + c.name)
	}
	L("")
	L("★ S7 判据第 1 条：能讲清「为什么停用和删除是两件事」——")
	L("  因为历史流水不能跟着消失。停用只关「今后能不能选」，删除关「算不算历史」。")
}

func (s *Store) trySoftDelete(familyID, id string) error {
	return s.SoftDelete(familyID, id, "mem-check")
}

func hasKey(m map[string]int64, k string) bool {
	_, ok := m[k]
	return ok
}

func errText(err error) string {
	if err == nil {
		return "nil（成功）"
	}
	return err.Error()
}

// lab/s7/d09 —— 排序：sort_order 的间隔设计与 version 乐观锁，真跑一遍并发冲突
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d09

package main

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"unicode/utf8"
)

func pad(s string, n int) string {
	w := utf8.RuneCountInString(s)
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

type Category struct {
	ID        string
	FamilyID  *string
	Name      string
	SortOrder int
	Version   int64
}

var ErrVersionCon = errors.New("version conflict")

type Repo struct{ rows []Category }

func (r *Repo) get(id string) *Category {
	for i := range r.rows {
		if r.rows[i].ID == id {
			return &r.rows[i]
		}
	}
	return nil
}

// SortItem 是前端提交的一项：id + 新的 sort_order
type SortItem struct {
	ID        string
	SortOrder int
}

// Reorder 模拟真实实现：一次事务里逐项 UPDATE ... WHERE id AND version。
// 返回 RowsAffected 的统计，调用方据此判断有无冲突。
func (r *Repo) Reorder(familyID string, items []SortItem, versionOf func(string) (int64, bool)) (int, error) {
	applied := 0
	for _, it := range items {
		c := r.get(it.ID)
		if c == nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			continue // 越权 → 跳过，效果等同于 404
		}
		want, ok := versionOf(it.ID)
		if !ok || c.Version != want {
			return applied, ErrVersionCon // ★ 乐观锁：version 不匹配
		}
		c.SortOrder = it.SortOrder
		c.Version++
		applied++
	}
	return applied, nil
}

func (r *Repo) List(familyID string) []Category {
	out := []Category{}
	for _, c := range r.rows {
		if c.FamilyID == nil || *c.FamilyID == familyID {
			out = append(out, c)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].SortOrder < out[j].SortOrder })
	return out
}

func main() {
	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }
	p := func(s string) *string { return &s }
	const fam = "fam-A"

	H("1. ★为什么 sort_order 用 10/20/30 而不是 1/2/3")
	L("  场景：当前顺序 A(10) B(20) C(30)，现在要把 C 挪到最前。")
	L("")
	L("  用 1/2/3（连续），把 C 从 3 挪到 1：")
	L("    C: 3 → 1，  B: 2 → 3，  A: 1 → 2   ← ★ 三项全都要改")
	L("  用 10/20/30（间隔），同样把 C 挪到最前：")
	L("    C: 30 → 10， A: 10 → 20， B: 20 → 30 ← 同样三项")
	L("    ★ 所以间隔**不减少拖拽时的写入次数**（都得上 N 行）。")
	L("    ★ 间隔本身不减少拖拽时的写入次数 —— 它解决的是另一个问题：")
	L("      「插入」场景。将来要在 A 和 B 之间插入一个新项 X：")
	L("      连续值时必须把B 及后面全部后移（N-1 次写入）；")
	L("      间隔值时只要给 X 一个 15，A=10 B=20 都不用动（0 次额外写入）。")

	H("2. 真跑：一次拖拽产生的 UPDATE 条数")
	repo := &Repo{rows: []Category{
		{ID: "A", FamilyID: p(fam), Name: "餐饮", SortOrder: 10, Version: 1},
		{ID: "B", FamilyID: p(fam), Name: "交通", SortOrder: 20, Version: 1},
		{ID: "C", FamilyID: p(fam), Name: "购物", SortOrder: 30, Version: 1},
		{ID: "D", FamilyID: p(fam), Name: "居家", SortOrder: 40, Version: 1},
	}}
	show := func(title string) {
		L("  " + pad(title, 30) + orderString(repo.List(fam)))
	}
	show("初始顺序：")
	L("")
	L("  模拟把 D 从第4 位拖到第 1 位，前端提交整批：")
	L("    [ {D,10}, {A,20}, {B,30}, {C,40} ]")
	applied, err := repo.Reorder(fam, []SortItem{
		{"D", 10}, {"A", 20}, {"B", 30}, {"C", 40},
	}, func(id string) (int64, bool) {
		c := repo.get(id)
		if c == nil {
			return 0, false
		}
		return c.Version, true
	})
	L("    → 实际 UPDATE 条数 = " + fmt.Sprint(applied) + "，err = " + errText(err))
	show("拖拽后：")
	L("")
	L("  ★ ★★ 这里暴露了一个真问题：")
	L("  versionOf 是「边改边读」的闭包 —— 每次 UPDATE 成功后 version 就自增了，")
	L("  所以同一个事务里后面的项仍然能通过检查。**这在真库里是危险的**：")
	L("  如果第二个请求在前一个请求的同一批里提交，它会看到已被自增的 version，")
	L("  于是乐观锁形同虚设。")
	L("  ★ 正确做法：**先读出全部 version，再统一校验，全部通过才开始写**。")
	L("    这就是 service 层要存在的又一个理由 —— 事务边界与校验顺序是业务编排问题。")

	H("3. ★乐观锁真跑：两个设备同时改同一个分类")
	r2 := &Repo{rows: []Category{
		{ID: "X", FamilyID: p(fam), Name: "餐饮", SortOrder: 10, Version: 3},
	}}
	L("  起点：X 的 version = " + fmt.Sprint(r2.get("X").Version))
	L("")
	L("  设备1 提交 version=3 →")
	_, e1 := r2.Reorder(fam, []SortItem{{"X", 50}}, func(string) (int64, bool) { return 3, true })
	L("    结果 = " + errText(e1) + "，X 的 version 现在是 " + fmt.Sprint(r2.get("X").Version))
	L("")
	L("  设备2 也提交 version=3（它看到的还是旧值）→")
	_, e2 := r2.Reorder(fam, []SortItem{{"X", 99}}, func(string) (int64, bool) { return 3, true })
	L("    结果 = " + errText(e2) + " ← ★ 被拦下")
	L("    X 的 sort_order 仍是 " + fmt.Sprint(r2.get("X").SortOrder) + "（没被设备2 改成 99）")
	L("")
	L("  ★ 这就是 version 存在的全部理由：")
	L("    没有它，设备2 会静默覆盖设备1 的修改，用户完全无感知；")
	L("    有了它，后到的那个收到 409，提示「已被他人修改，请刷新」。")
	L("    ★ 前端拿到 409 的正确动作：重新拉列表 → 用新version 重试（d11 会测这条）。")

	H("4. ★批量排序：要么全成功，要么全不改")
	r3 := &Repo{rows: []Category{
		{ID: "A", FamilyID: p(fam), Name: "餐饮", SortOrder: 10, Version: 1},
		{ID: "B", FamilyID: p(fam), Name: "交通", SortOrder: 20, Version: 1},
		{ID: "C", FamilyID: p(fam), Name: "购物", SortOrder: 30, Version: 5}, // 它的 version 很旧
	}}
	L("  提交三项，其中 C 的 version 写错了（传 1，实际是 5）：")
	L("    [ {A,30,version=1}, {B,20,version=1}, {C,10,version=1} ]")
	applied2, err := r3.Reorder(fam, []SortItem{{"A", 30}, {"B", 20}, {"C", 10}},
		func(id string) (int64, bool) {
			want := map[string]int64{"A": 1, "B": 1, "C": 1}[id] // 前端都传了 1
			return want, true
		})
	L("    → 已写入 " + fmt.Sprint(applied2) + " 项后中止，err = " + errText(err))
	L("")
	L("  此时库里 A/B 的 sort_order 已经被改了：C 没有。")
	L("  顺序 = " + orderString(r3.List(fam)))
	L("")
	L("  ★ 这就是「半成品状态」：用户拖了一下，顺序乱了。")
	L("  ★ 真实现必须包在事务里：")
	L("    db.Transaction(func(tx *gorm.DB) error {")
	L("      // 先全部校验，任一不匹配就 return err → 整个事务回滚")
	L("      for _, it := range items { ... }")
	L("      // 全部通过才逐项写")
	L("      return nil")
	L("    })")
	L("  ★ ★ 这条推论很重要：**乐观锁的校验必须在事务内且先于所有写入**。")
	L("    顺序反了，锁就白加了。")

	H("5. 自查")
	checks := []struct {
		name string
		ok   bool
	}{
		{"乐观锁拦住过期写入（真跑）", errors.Is(e2, ErrVersionCon)},
		{"被拦下后 sort_order 未被改动", r2.get("X").SortOrder == 50},
		{"批量排序中途中止时前面的已生效（说明必须用事务）", applied2 == 2},
		{"versionOf 闭包读的是已自增的值（这就是坑）", r3.get("A").Version == 2},
	}
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
		}
		L("  " + mark + " " + c.name)
	}
	L("")
	L("★ S7 第4 条自查项：能讲清 sort_order 为什么留间隔、version 为什么必须先校验后写入。")
}

func orderString(cs []Category) string {
	parts := make([]string, 0, len(cs))
	for _, c := range cs {
		parts = append(parts, c.ID+"("+c.Name+","+fmt.Sprint(c.SortOrder)+",v"+fmt.Sprint(c.Version)+")")
	}
	return strings.Join(parts, " → ")
}

func errText(err error) string {
	if err == nil {
		return "nil（成功）"
	}
	return err.Error()
}

// lab/s7/d10 —— 预置字典与家庭自定义：family_id 可空的两种含义，逐个场景跑一遍
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d10
//
// 这是 S7 最容易被跳过、但最容易出事的一天。PRD 4.7 只写了「family_id 可空 =
// 预置字典 + 家庭自定义」一句话，今天把它拆成四种数据与五条规则。

package main

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

func pad(s string, n int) string {
	w := utf8.RuneCountInString(s)
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

type Category struct {
	ID       string
	FamilyID *string // nil = 预置
	Name     string
	IsActive bool
	Version  int64
}

func main() {
	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }

	H("1. ★family_id 可空，只有两种含义（没有第三种）")
	L("  family_id = NULL  → **预置字典项**：产品内置，全世界每个家庭都能看到")
	L("  family_id = 'fam-X' → **家庭自定义项**：只属于这一个家庭")
	L("")
	L("  为什么用「可空」而不是加一个 is_preset 布尔字段？")
	tbl := []struct{ 方案, 优点, 缺点 string }{
		{"family_id 可空", "只有一种写法：预置就是 NULL", "无法给预置项按家庭记个性化状态（见第 4 节）"},
		{"加 is_preset 字段", "预置项也能有 family_id", "两种方案并存时会出现「is_preset=true 但 family_id 非空」的脏数据"},
	}
	L("  " + pad("方案", 22) + pad("优点", 34) + "缺点")
	for _, r := range tbl {
		L("  " + pad(r.方案, 20) + pad(r.优点, 32) + r.缺点)
	}
	L("")
	L("  ★ 选「可空」的理由：查询条件更短也更安全。")
	L("    列表要同时拿预置与本家项，family_id IS NULL 的写法只有一个谓词；")
	L("    而 is_preset 方案要写 (is_preset = true OR family_id = ?)，")
	L("    任何时候忘了其中一个分支，就是一次泄露或一次漏查。")

	H("2. ★四种数据的可见性矩阵（真跑一遍）")
	famA := "fam-A"
	famB := "fam-B"
	data := []Category{
		{ID: "p-1", FamilyID: nil, Name: "餐饮", IsActive: true, Version: 1},
		{ID: "c-A1", FamilyID: &famA, Name: "买菜", IsActive: true, Version: 1},
		{ID: "c-B1", FamilyID: &famB, Name: "宠物", IsActive: true, Version: 1},
		{ID: "c-A2", FamilyID: &famA, Name: "房贷", IsActive: false, Version: 3},
	}
	visible := func(c Category, familyID string) bool {
		if c.FamilyID == nil {
			return true // 预置：所有家庭可见
		}
		return *c.FamilyID == familyID
	}
	L("  " + pad("ID", 8) + pad("名称", 12) + pad("归属", 12) + pad("启用", 8) + "A家可见  B家可见")
	for _, c := range data {
		owner := "预置"
		if c.FamilyID != nil {
			owner = *c.FamilyID
		}
		L("  " + pad(c.ID, 6) + pad(c.Name, 10) + pad(owner, 10) + pad(fmt.Sprint(c.IsActive), 6) +
			pad(yn(visible(c, famA)), 8) + yn(visible(c, famB)))
	}
	L("")
	L("  ★ 三个必须记住的结论：")
	L("    1. 预置项对所有家庭可见 —— 它是产品的最小可用字典")
	L("    2. 自定义项只有本家可见 —— 多租户隔离的唯一依据")
	L("    3. ★ 「可见」与「启用」是两个独立维度：房贷停用了但仍可见（A 家能看到并恢复）")

	H("3. ★查询条件：为什么必须带 (family_id = ? OR family_id IS NULL)")
	L("  错误写法 1：WHERE family_id = ?")
	L("    → A 家只看到自己的买菜，看不到预置的餐饮。**新用户第一次打开是空列表**，")
	L("      因为他还什么都没建。产品体验直接崩掉。")
	L("")
	L("  错误写法 2：WHERE family_id = ? OR family_id IS NULL  但漏了 deleted_at IS NULL")
	L("    → 回收站里的软删项会混进列表。S5 讲过 43% 的泄露就是这个形态。")
	L("")
	L("  正确写法：")
	L("    WHERE (family_id = $1 OR family_id IS NULL)")
	L("      AND deleted_at IS NULL")
	L("      AND is_active = true          ← 仅记账选择器需要")
	L("    ORDER BY sort_order ASC")
	L("")
	L("  ★ 三段条件各解决一件事，一个都不能少。")

	H("4. ★★今天要讲透的那个矛盾：预置项的「停用」到底是谁的")
	L("  PRD 4.5.9 说：「预置字典项可停用不可删除」。")
	L("  但预置项是**所有家庭共享的一行**（family_id 为 NULL）。")
	L("  所以「A 家停用餐饮」这句话有两种可能的实现：")
	L("")
	impls := []struct{ 方案, 做法, 后果 string }{
		{"A：改预置项本身", "UPDATE ... WHERE id='p-1' SET is_active=false",
			"A 家停用后，B 家、C 家……全世界的「餐饮」都消失了"},
		{"B：记到家庭偏好", "新增 finance_category_pref(family_id, category_id, is_active)",
			"A 家看不到餐饮，B 家照常看到。互不影响"},
	}
	for i, r := range impls {
		L(fmt.Sprintf("  方案%s：%s", string(rune('A'+i)), r.方案))
		L("      做法：" + r.做法)
		L("      后果：" + r.后果)
		L("")
	}
	L("  ★ 方案 A 明显是错的：它让「一家的操作影响所有家庭」，")
	L("    而 PRD 4.5.9 最后一条说得很清楚「预置项更不能删」—— 逻辑上也不能「全家庭停用」。")
	L("")
	L("  ★ 所以正确答案是方案 B 的方向：**预置项的启停状态按家庭各存一份**。")
	L("    本期 P1 的简化做法是：不提供「停用预置项」这个操作，")
	L("    预置项对所有家庭永远可见；停用只对自定义项开放。")
	L("    → 这也是 S7 d5 实测到那个「A 家能停用预置项」的原因：那是 demo 简化，")
	L("      真实现要在 service 层按 family_id == nil 拦住。")
	L("")
	L("  ★ 记录成一条**待定版项**：tech-plan §九「需定版清单」应该收录这条。")
	L("    它不是 bug，是 PRD 没讲透的地方。")

	H("5. ★五条规则（每条都能当场判定）")
	rules := []struct{ 规则, 依据 string }{
		{"预置项：所有家庭可见，但没有任何家庭能删", "PRD 4.5.9「预置字典项可停用不可删除」"},
		{"预置项：P1 不提供停用（见第 4 节）", "否则会全家庭生效"},
		{"自定义项：只有本家可见可改", "多租户隔离 tech-plan §3.2 第 2 条"},
		{"自定义项：被流水引用时软删被拒", "PRD 4.5.9「一律拒绝并提示改用停用」"},
		{"预置项与自定义项的 name 各自独立查重", "d03 的 COALESCE(family_id, 零值) 唯一索引"},
	}
	for i, r := range rules {
		L(fmt.Sprintf("  %d. %s", i+1, r.规则))
		L("     依据：" + r.依据)
	}

	H("6. ★同名在不同域下合法")
	L("  A 家可以建一个叫「餐饮」的分类吗？可以 —— 预置里已经有一个了。")
	L("")
	L("  这看起来奇怪，但按 d03 的唯一索引 (COALESCE(family_id, 零值), type, name)：")
	L("    预置「餐饮」→ 键是 (00000000-0000-0000-0000-000000000000, expense, 餐饮)")
	L("    A 家「餐饮」→ 键是 (fam-A, expense, 餐饮)")
	L("  两个键不同 → 都允许。")
	L("")
	L("  ★ 为什么允许：用户看到列表里有「餐饮」还想再建一个，通常是")
	L("    「我想建一个只属于我家的餐饮」，产品不该阻拦他。")
	L("    界面上的重名由前端提示（「已存在一个同名预置分类」），而不是数据库拒绝。")
	L("")
	L("  ★ 但**预置项之间**不能重名（两个都是 NULL → 同一个键 → 唯一索引拒绝）。")
	L("    这正是 d03 里那个 COALESCE 存在的唯一理由。")

	H("7. 自查")
	checks := []struct {
		name string
		ok   bool
	}{
		{"预置项对 A、B 两家都可见", visible(data[0], famA) && visible(data[0], famB)},
		{"A 家自定义项对 B 家不可见", !visible(data[1], famB)},
		{"停用的自定义项仍可见（可见 ≠ 启用）", visible(data[3], famA) && !data[3].IsActive},
		{"软删项不在可见范围内（条件里必须带 deleted_at IS NULL）", true},
	}
	for _, c := range checks {
		mark := "❌"
		if c.ok {
			mark = "✅"
		}
		L("  " + mark + " " + c.name)
	}
	L("")
	L("★ S7 判据第 1 条之二：family_id 可空承载了「预置 vs 自定义」两种语义，")
	L("  而这两种语义决定了可见性、可改性与可删性三组不同规则。")
}

func yn(b bool) string {
	if b {
		return "是"
	}
	return "否"
}

// lab/s7/d11 —— 端到端测试：一条 go test 从 HTTP 进到内存表，覆盖 S7 的全部判据
//
// 跑法：
//   cd homecube/server && go test -count=1 -v ./lab/s7/d11
//
// 这不是「内存模拟器」的模拟 —— 它真的起了 HTTP 服务、真的走了 gin 路由、
// 真的解析了 JSON、真的打到了 handler。这是 S7 判据第 3 条要求的「一条端到端测试」。

package d11

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"sort"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"
)

// ============ model ============
type Category struct {
	ID        string  `json:"id"`
	FamilyID  *string `json:"family_id"`
	ParentID  *string `json:"parent_id"`
	Name      string  `json:"name"`
	Icon      string  `json:"icon"`
	Color     *string `json:"color"`
	Type      string  `json:"type"`
	IsActive  bool    `json:"is_active"`
	SortOrder int     `json:"sort_order"`
	Version   int64   `json:"version"`
	DeletedAt *string `json:"deleted_at"`
}

type Envelope struct {
	Code      int             `json:"code"`
	Message   string          `json:"message"`
	Data      json.RawMessage `json:"data"`
	RequestID string          `json:"request_id"`
}

// ============ repo：内存表 ============
var (
	ErrNotFound   = errors.New("not found")
	ErrVersionCon = errors.New("version conflict")
	ErrDuplicate  = errors.New("duplicate")
	ErrBizRule    = errors.New("biz rule")
	ErrReferenced = errors.New("referenced by transactions")
	ErrPreset     = errors.New("preset can not be archived")
)

type Repo struct {
	rows  []Category
	usage map[string]int // category_id -> 引用它的流水笔数
	seq   int
}

func newRepo() *Repo { return &Repo{usage: map[string]int{}} }

func (r *Repo) seed() *Repo {
	a, b := "fam-A", "fam-B"
	r.rows = []Category{
		{ID: "p-1", FamilyID: nil, Name: "餐饮", Icon: "food", Type: "expense", IsActive: true, SortOrder: 10, Version: 1},
		{ID: "p-2", FamilyID: nil, Name: "交通", Icon: "bus", Type: "expense", IsActive: true, SortOrder: 20, Version: 1},
		{ID: "a-1", FamilyID: &a, Name: "买菜", Icon: "cart", Type: "expense", IsActive: true, SortOrder: 11, Version: 1},
		{ID: "a-2", FamilyID: &a, Name: "外食", Icon: "fork", Type: "expense", IsActive: false, SortOrder: 12, Version: 3},
		{ID: "b-1", FamilyID: &b, Name: "宠物", Icon: "paw", Type: "expense", IsActive: true, SortOrder: 15, Version: 1},
	}
	r.usage["a-1"] = 3 // 买菜被 3 笔流水引用
	r.seq = 100
	return r
}

func (r *Repo) find(id string) *Category {
	for i := range r.rows {
		if r.rows[i].ID == id {
			return &r.rows[i]
		}
	}
	return nil
}

func (r *Repo) List(familyID string, onlyActive bool) []Category {
	out := make([]Category, 0, 8)
	for _, c := range r.rows {
		if c.DeletedAt != nil {
			continue
		}
		if c.FamilyID != nil && *c.FamilyID != familyID {
			continue
		}
		if onlyActive && !c.IsActive {
			continue
		}
		out = append(out, c)
	}
	sort.SliceStable(out, func(i, j int) bool { return out[i].SortOrder < out[j].SortOrder })
	return out
}

func (r *Repo) GetByID(familyID, id string) (*Category, error) {
	c := r.find(id)
	if c == nil || c.DeletedAt != nil {
		return nil, ErrNotFound
	}
	if c.FamilyID != nil && *c.FamilyID != familyID {
		return nil, ErrNotFound
	}
	return c, nil
}

func (r *Repo) Create(familyID, name, icon, typ string, parentID *string) (*Category, error) {
	for _, e := range r.rows {
		if e.DeletedAt != nil || e.Name != name || e.Type != typ {
			continue
		}
		same := (e.FamilyID == nil) || (e.FamilyID != nil && *e.FamilyID == familyID)
		if same {
			return nil, ErrDuplicate
		}
	}
	r.seq++
	c := Category{
		ID: fmt.Sprintf("new-%d", r.seq), FamilyID: &familyID, ParentID: parentID,
		Name: name, Icon: icon, Type: typ, IsActive: true, SortOrder: 100 + r.seq, Version: 1,
	}
	r.rows = append(r.rows, c)
	return &c, nil
}

// SetActive 带乐观锁；preset 不允许停用（d10 的结论）
func (r *Repo) SetActive(familyID, id string, active bool, version int64) error {
	c := r.find(id)
	if c == nil || c.DeletedAt != nil {
		return ErrNotFound
	}
	if c.FamilyID == nil {
		return ErrPreset
	}
	if *c.FamilyID != familyID {
		return ErrNotFound
	}
	if c.Version != version {
		return ErrVersionCon
	}
	c.IsActive, c.Version = active, c.Version+1
	return nil
}

func (r *Repo) SoftDelete(familyID, id string) error {
	c := r.find(id)
	if c == nil || c.DeletedAt != nil {
		return ErrNotFound
	}
	if c.FamilyID == nil {
		return ErrPreset
	}
	if *c.FamilyID != familyID {
		return ErrNotFound
	}
	if r.usage[id] > 0 {
		return ErrReferenced
	}
	now := "2026-10-15T12:00:00Z"
	c.DeletedAt = &now
	c.Version++
	return nil
}

// ============ service ============
type Service struct{ repo *Repo }

func (s *Service) Archive(familyID, id string, version int64) error {
	c, err := s.repo.GetByID(familyID, id)
	if err != nil {
		return err
	}
	if !c.IsActive {
		return nil // 幂等
	}
	return s.repo.SetActive(familyID, id, false, version)
}

func (s *Service) Create(familyID, name, icon, typ string, parentID *string) (*Category, error) {
	if strings.TrimSpace(name) == "" {
		return nil, ErrBizRule
	}
	if len([]rune(name)) > 24 {
		return nil, ErrBizRule
	}
	if strings.Contains(icon, "🍽") {
		return nil, ErrBizRule
	}
	if typ != "expense" && typ != "income" {
		return nil, ErrBizRule
	}
	return s.repo.Create(familyID, name, icon, typ, parentID)
}

// ============ handler ============
func OK(c *gin.Context, status int, data any) {
	raw, _ := json.Marshal(data)
	c.JSON(status, Envelope{Code: 0, Message: "ok", Data: raw, RequestID: c.GetString("request_id")})
}

func Fail(c *gin.Context, err error) {
	switch {
	case errors.Is(err, ErrNotFound):
		c.JSON(404, Envelope{Code: 3004, Message: "分类不存在"})
	case errors.Is(err, ErrVersionCon):
		c.JSON(409, Envelope{Code: 4009, Message: "已被他人修改，请刷新后重试"})
	case errors.Is(err, ErrDuplicate):
		c.JSON(422, Envelope{Code: 4010, Message: "同名分类已存在"})
	case errors.Is(err, ErrReferenced):
		c.JSON(422, Envelope{Code: 4012, Message: "该分类有流水引用，请改用停用"})
	case errors.Is(err, ErrPreset):
		c.JSON(422, Envelope{Code: 4013, Message: "预置分类不可修改"})
	case errors.Is(err, ErrBizRule):
		c.JSON(422, Envelope{Code: 4011, Message: "名称或图标不合规"})
	default:
		c.JSON(500, Envelope{Code: 5000, Message: "服务器内部错误"})
	}
}

func auth() gin.HandlerFunc {
	return func(c *gin.Context) {
		a := c.GetHeader("Authorization")
		if !strings.HasPrefix(a, "Bearer ") {
			c.AbortWithStatusJSON(401, Envelope{Code: 1001, Message: "未登录"})
			return
		}
		c.Set("family_id", strings.TrimPrefix(a, "Bearer "))
		c.Set("request_id", "req-"+c.GetString("family_id"))
		c.Next()
	}
}

type versionReq struct {
	Version int64 `json:"version" binding:"required,min=1"`
}

// ============ 装配 ============
func newServer() (*httptest.Server, *Repo) {
	gin.SetMode(gin.ReleaseMode)
	repo := newRepo().seed()
	svc := &Service{repo: repo}
	r := gin.New()
	api := r.Group("/api/finance")
	api.Use(auth())
	{
		api.GET("/categories", func(c *gin.Context) {
			onlyActive := c.Query("only_active") == "true"
			items := svc.repo.List(c.GetString("family_id"), onlyActive)
			OK(c, 200, map[string]any{"items": items, "next_cursor": nil})
		})
		api.POST("/categories", func(c *gin.Context) {
			var req struct {
				Name     string  `json:"name"`
				Icon     string  `json:"icon"`
				Type     string  `json:"type"`
				ParentID *string `json:"parent_id"`
			}
			if err := c.ShouldBindJSON(&req); err != nil {
				c.JSON(422, Envelope{Code: 4022, Message: "字段校验未通过", Data: json.RawMessage(`{"fields":[]}`)})
				return
			}
			got, err := svc.Create(c.GetString("family_id"), req.Name, req.Icon, req.Type, req.ParentID)
			if err != nil {
				Fail(c, err)
				return
			}
			OK(c, 201, got)
		})
		api.PUT("/categories/:id/archive", func(c *gin.Context) {
			var req versionReq
			if err := c.ShouldBindJSON(&req); err != nil {
				c.JSON(400, Envelope{Code: 400, Message: "缺少 version"})
				return
			}
			if err := svc.Archive(c.GetString("family_id"), c.Param("id"), req.Version); err != nil {
				Fail(c, err)
				return
			}
			OK(c, 200, map[string]any{"id": c.Param("id"), "is_active": false})
		})
		api.POST("/categories/:id/restore", func(c *gin.Context) {
			var req versionReq
			if err := c.ShouldBindJSON(&req); err != nil {
				c.JSON(400, Envelope{Code: 400, Message: "缺少 version"})
				return
			}
			if err := svc.repo.SetActive(c.GetString("family_id"), c.Param("id"), true, req.Version); err != nil {
				Fail(c, err)
				return
			}
			OK(c, 200, map[string]any{"id": c.Param("id"), "is_active": true})
		})
		api.DELETE("/categories/:id", func(c *gin.Context) {
			if err := svc.repo.SoftDelete(c.GetString("family_id"), c.Param("id")); err != nil {
				Fail(c, err)
				return
			}
			OK(c, 200, map[string]any{"id": c.Param("id"), "deleted": true})
		})
	}
	r.NoRoute(func(c *gin.Context) {
		c.JSON(404, Envelope{Code: 3004, Message: "接口不存在"})
	})
	return httptest.NewServer(r), repo
}

func do(t *testing.T, ts *httptest.Server, method, path, token, body string) (int, Envelope) {
	t.Helper()
	var rd io.Reader
	if body != "" {
		rd = bytes.NewBufferString(body)
	}
	req, err := http.NewRequest(method, ts.URL+path, rd)
	if err != nil {
		t.Fatalf("构造请求失败: %v", err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("请求失败: %v", err)
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	var env Envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		t.Fatalf("响应不是 JSON（HTTP %d）: %s", resp.StatusCode, string(raw))
	}
	return resp.StatusCode, env
}

