func Test06_OptimisticLockConflict(t *testing.T) {
	ts, repo := newServer()
	defer ts.Close()

	if code, _ := do(t, ts, "PUT", "/api/finance/categories/a-1/archive", "fam-A", `{"version":1}`); code != 200 {
		t.Fatal("第一次停用应成功")
	}
	code, env := do(t, ts, "PUT", "/api/finance/categories/a-1/archive", "fam-A", `{"version":1}`)
	// 注意：第二次是「已停用」，service 的幂等分支先命中，所以这里返 200 而不是 409。
	// 真正测乐观锁要用 restore 冲突或直接对不同项操作，见下一个用例。
	if code != 200 && code != 409 {
		t.Fatalf("重复停用期望 200（幂等）或 409，得到 %d", code)
	}
	_ = env

	// ★ 真正冲突：拿过期的 version 去 restore（此时库里 version 已是 2）
	code, env = do(t, ts, "POST", "/api/finance/categories/a-1/restore", "fam-A", `{"version":1}`)
	if code != 409 || env.Code != 4009 {
		t.Fatalf("★ 用过期 version 期望 409/4009，得到 %d/%d", code, env.Code)
	}
	if repo.find("a-1").IsActive != false {
		t.Fatal("★ 乐观锁必须拦住写入，is_active 不应变")
	}
}

