// lab/s7/d12 —— S7 收口：判据自查 + 费曼复盘（把 12 天的话逐条判定一遍）
//
// 跑法：
//   cd homecube/server && go run ./lab/s7/d12

package main

import (
	"fmt"
	"strings"
	"unicode/utf8"
)

func pad(s string, n int) string {
	w := utf8.RuneCountInString(s)
	if w >= n {
		return s
	}
	return s + strings.Repeat(" ", n-w)
}

func main() {
	L := func(s string) { fmt.Println(s) }
	H := func(s string) { fmt.Println("\n===== " + s + " =====") }

	H("1. S7 的三条通过判据，逐条自查")
	criteria := []struct{ n, 判据, 怎么验, 我能吗 string }{
		{"1", "分类的增删改查 + 排序 + 停用（不影响历史数据）全通",
			"d11 的15 个用例全过就是验完了；S7 d11 实测 PASS",
			"能"},
		{"2", "讲清：为什么「停用」和「删除」是两件事，为什么历史流水不能跟着消失",
			"d8 第 1 节实测：停用后统计仍是 80 元；第 4 节实测：被引用时软删被拒",
			"能"},
		{"3", "有一条端到端测试",
			"lab/s7/d11：从 HTTP 进、gin 路由、JSON 解析、handler、service、repo 全链路",
			"能"},
	}
	L("  # " + pad("判据", 40) + pad("怎么验", 40) + "结果")
	for _, c := range criteria {
		L("  " + c.n + " " + pad(c.判据, 38) + pad(c.怎么验, 38) + c.我能吗)
	}
	L("")
	L("  ★ 判据 1 和 3 都是「做过」，判据 2 是「讲得出」。")
	L("    这正是 S7 与 S0-S6 的差别：前面判「能讲清」，这里判「能交付 + 能解释」。")

	H("2. 费曼复盘：12 天里最容易说错的 12 句话")
	// claim 是「学生（只会React/TS 的人）会说的 12 句话」+ 判定 + 纠正
	type claim struct {
		id         int
		topic      string
		verdict    string // 对 / 半对 / 错
		quote      string // 他会说的话
		correction string // 纠正
	}
	claims := []claim{
		{
			id: 1, topic: "五步", verdict: "半对",
			quote: "先写代码，接口回头再补。",
			correction: "顺序不能反。不先定契约，前端会照着你的临时实现写；\n" +
				"契约一旦被前端依赖，改字段就成了破坏性变更（S2 那四个版本就是这么来的）。",
		},
		{
			id: 2, topic: "DDL", verdict: "错",
			quote: "family_id 设成 NOT NULL，反正是每个家庭都有一份。",
			correction: "预置项的 family_id 必须是 NULL。设成 NOT NULL 就没有「新用户开箱可用」的\n" +
				"最小字典，第一次打开是空列表。",
		},
		{
			id: 3, topic: "唯一索引", verdict: "半对",
			quote: "加个 UNIQUE(family_id, type, name) 就行了。",
			correction: "SQL 里 NULL 不参与唯一约束，等于预置项可以重名一百个。\n" +
				"必须写 UNIQUE(COALESCE(family_id, 零值), type, name)。",
		},
		{
			id: 4, topic: "repo", verdict: "对",
			quote: "GetByID 里越权就返回 403，语义更清楚。",
			correction: "（这句本身对，但要注意执行位置）repo 层只有一个 ErrNotFound；\n" +
				"403 语义是对的**响应**，由 handler 决定状态码。",
		},
		{
			id: 5, topic: "repo", verdict: "错",
			quote: "判断分类有没有被流水引用，直接 join finance_transaction 不就行了。",
			correction: "★违反 tech-plan §3.2 第 2 条：repo 不得select 别的 schema 的表。\n" +
				"要走platform 定义的接口去问。",
		},
		{
			id: 6, topic: "handler", verdict: "错",
			quote:      "family_id 从请求参数里取，方便调试。",
			correction: "★越权开关交给了前端。多家庭账号必须靠服务端签发新 token（tech-plan §8.5）。",
		},
		{
			id: 7, topic: "handler", verdict: "错",
			quote: "校验失败统一返 400 就够了。",
			correction: "★S7 d5 实测：JSON 语法错返 400，字段规则不满足返 422。\n" +
				"不区分的话前端没法把光标定位到具体字段。",
		},
		{
			id: 8, topic: "乐观锁", verdict: "半对",
			quote: "带上 version 就安全了。",
			correction: "带 version 只是必要条件。★d9 实测：批量排序必须**先全量校验再统一写**，\n" +
				"否则边校验边写，锁形同虚设。",
		},
		{
			id: 9, topic: "停用", verdict: "错",
			quote: "停用就是 is_active 设为 false，然后从列表里 filter 掉。",
			correction: "★列表页**要能看到**停用项（否则没法恢复）。只有记账选择器才过滤。\n" +
				"S7 d11 的 Test01 专门断言了这一点。",
		},
		{
			id: 10, topic: "预置项", verdict: "错",
			quote: "PRD 说预置项可停用，那就是能停用。",
			correction: "★d10 实测的陷阱：预置项是所有家庭共享的一行，A 家停用它就全世界的都没了。\n" +
				"P1 的正确做法是**不提供**停用预置项这个操作。",
		},
		{
			id: 11, topic: "前端", verdict: "半对",
			quote: "列表页用 onMounted 拉数据就行。",
			correction: "用 onLoad + onShow。页面栈 = keep-alive（S6 d06 实测），\n" +
				"onMounted 只跑一次，用户 navigateBack 回来会看到旧数据。",
		},
		{
			id: 12, topic: "空列表", verdict: "错",
			quote: "查不到就返回 nil，前端处理一下就行。",
			correction: "★nil slice 序列化成 null，前端 res.items.map 直接 TypeError。\n" +
				"必须是 make([]T, 0) 或 []T{}（d11 Test15 断言了）。",
		},
	}
	right, wrong, half := 0, 0, 0
	L("  # " + pad("知识点", 10) + pad("判定", 8) + "学生（React/TS 视角）的原话")
	for _, c := range claims {
		L(fmt.Sprintf("  %2d %s %s %s", c.id, pad(c.topic, 8), pad(c.verdict, 6), c.quote))
		switch c.verdict {
		case "对":
			right++
		case "错":
			wrong++
		default:
			half++
		}
	}
	L("")
	L(fmt.Sprintf("  12 句里：%d 句完全对，%d 句半对，%d 句错。", right, half, wrong))
	L("  ★ 错得最多的是「预置项」和「空列表」——")
	L("    前者是 PRD 没讲透，后者是 Go 与 JS 的零值差异，都不是「理解问题」。")

	H("3. 逐条掰回来（只讲错的与半对的）")
	for _, c := range claims {
		if c.verdict == "对" {
			continue
		}
		L("  [" + fmt.Sprint(c.id) + "] " + c.topic + " —— " + c.verdict)
		for _, line := range strings.Split(c.correction, "\n") {
			L("      " + line)
		}
		L("")
	}
	L("  ★★ 最需要记住的一句（第 10 条）：")
	L("    「family_id 可空」这四个字，承载了「预置 vs 自定义」两种语义，")
	L("    而这两种语义决定了三组不同的规则（可见性 / 可改性 / 可删性）。")
	L("    PRD 只写了一句，但你必须能推出全部规则 —— 否则就会写出「A 家停用影响全世界」。")

	H("4. ★五步里，哪一步最容易偷懒")
	type step struct{ n, 名称, 偷懒形态, 后果 string }
	steps := []step{
		{"1", "定契约", "先写代码，接口回头补",
			"前端照着临时实现写，三年后没人说得清哪个字段是准的"},
		{"2", "建表", "用 AutoMigrate 自动建表",
			"★ 生产库结构不可追溯；AutoMigrate 不会建 CHECK 约束与部分唯一索引"},
		{"3", "后端", "handler 里直接调 repo，不写 service",
			"业务规则散落各处；第二个入口（批量操作）就要重写一遍"},
		{"4", "前端", "列表页写死数组，不接接口",
			"联调时才发现契约形状对不上，前后端同时返工"},
		{"5", "联调", "手工点几次就算测过了",
			"★ S5 d22 讲的 43% 泄露就是「跑了一遍有 bug 的版本」这种方式漏掉的"},
	}
	L("  " + pad("步骤", 8) + pad("偷懒形态", 34) + "后果")
	for _, s := range steps {
		L("  " + pad(s.n+" "+s.名称, 6) + pad(s.偷懒形态, 32) + s.后果)
	}
	L("")
	L("  ★ 特别注意第 2 步：GORM 的 AutoMigrate 只处理字段，")
	L("    不会创建 CHECK 约束、也不会创建带 WHERE 的部分唯一索引。")
	L("    而 d03 里那三个索引正是靠手写 DDL 才有的。")

	H("5. S8 之前要确认的三件事")
	todo := []struct{ what, how string }{
		{"迁移在真库上跑过（up → down → up 结构 diff 为空）",
			"本机没有 PostgreSQL，这一步 S7 没做。判据写在 d3 第 6 节，联调时补。"},
		{"待定版项已上报：预置项的停用语义",
			"d10 第 4 节结论：P1 不提供停用预置项；长期方案是 finance_category_pref 表。\n              记进 tech-plan §九「需定版清单」。"},
		{"待改进项：422 的 fields 应是结构体数组而不是字符串数组",
			"d7 第 5 节：现在前端靠中文文案反推字段，很脆弱。\n              契约应改成 [{\"field\":\"type\",\"message\":\"...\"}]。"},
	}
	for _, t := range todo {
		L("  · " + t.what)
		for _, line := range strings.Split(t.how, "\n") {
			L("      " + line)
		}
		L("")
	}
	L("  ★ 前端视角做后端最容易漏的一件事：**契约的形状要能被机器检查**。")
	L("    「空列表是[] 不是 null」「越权返 404」「预置项不可改」这三条，")
	L("    都应该在 go test 里有断言，而不是靠人记得。d11 就是这个作用。")

	H("6. 最后：把 S7 讲给下一个人听（30 秒版）")
	L("  「分类是第一个功能域，因为它不依赖别的域、被别的域依赖。")
	L("   五步是定契约、建表、repo→service→handler、前端两页、联调加测试。")
	L("   最核心的一件事是停用和删除分成两件事：因为历史流水不能跟着消失，")
	L("   停用只关「今后能不能选」，删除关「还算不算历史」，两个字段正交。")
	L("   第二件事是 family_id 可空承载了预置与自定义两种语义，")
	L("   它决定了可见性、可改性、可删性三组规则 ——")
	L("   PRD 只写了一句，但你要能推出全部规则。」")
}
